<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<link rel="preconnect" href="https://cdn.savedly.net" crossorigin>
<meta name="viewport" content="width=device-width, initial-scale=1, minimum-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover">
<meta name="theme-color" content="#01131d">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<meta name="referrer" content="strict-origin-when-cross-origin">
<title>GipaPlay</title>
<link rel="icon" type="image/png" href="data:image/png;base64,">
<link rel="apple-touch-icon" href="data:image/png;base64,">

<style>
  :root{
    --bg:#01131d;--panel:#112134;--text:#f4f4f7;--muted:#b4c3d3;
    --accent:#cd1f1f;--accent2:#8f0f4e;
    --side:4.5rem;
    --card-w:10.5rem;
    --gap:.75rem;
  }
  html{font-size:16px}
  @media (min-width:1600px){html{font-size:18px}}
  @media (min-width:1920px){html{font-size:21px}}
  @media (min-width:2560px){html{font-size:28px}}
  @media (min-width:3440px){html{font-size:36px}}
  @media (min-width:5000px){html{font-size:52px}}
  @media (max-width:600px){:root{--card-w:7.6rem;--gap:.55rem}}

  *{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
  /* Ocultar barras de scroll en toda la página (se sigue pudiendo desplazar) */
  html,body,*{scrollbar-width:none;-ms-overflow-style:none}
  *::-webkit-scrollbar,html::-webkit-scrollbar,body::-webkit-scrollbar{display:none;width:0;height:0}
  html,body{background:var(--bg);color:var(--text);font-family:"Segoe UI",Roboto,Helvetica,Arial,sans-serif;overflow-x:hidden}
  body{min-height:100vh;min-height:100dvh}
  svg{width:1.25rem;height:1.25rem;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}

  /* Barra lateral */
  .sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--side);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1.9rem;z-index:30;background:linear-gradient(90deg,rgba(0,0,0,.8),transparent)}
  .sidebar button{background:none;border:0;color:#9a9aa8;cursor:pointer;padding:.5rem;position:relative;transition:color .2s,transform .2s;display:grid;place-items:center}
  .sidebar button:hover{color:#fff;transform:scale(1.15)}
  .sidebar button.active{color:#fff}
  .sidebar button.active::after{content:"";position:absolute;left:.5rem;right:.5rem;bottom:-.25rem;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2));border-radius:2px}
  @media (max-width:760px){
    :root{--side:0rem}
    .sidebar{top:auto;left:0;right:0;bottom:0;width:100%;flex-direction:row;justify-content:space-around;gap:0;background:rgba(1,19,29,.96);backdrop-filter:blur(10px);border-top:1px solid #183049;padding-bottom:env(safe-area-inset-bottom);height:calc(3.6rem + env(safe-area-inset-bottom))}
    .sidebar button.active::after{bottom:0}
    body{padding-bottom:calc(4rem + env(safe-area-inset-bottom))}
  }

  /* Marca */
  .topbar{position:absolute;top:0;left:var(--side);right:0;z-index:10;display:flex;align-items:center;padding:1rem 2rem}
  .logo{display:flex;align-items:center;gap:.55rem;font-weight:900;font-size:1.35rem;letter-spacing:-.01em}
  .logo i{width:1.7rem;height:1.7rem;border-radius:.45rem;background:linear-gradient(135deg,var(--accent),var(--accent2));display:grid;place-items:center;font-style:normal;font-size:1rem;color:#fff}
  .logo img{display:block;width:auto}
  .logo-bird{height:3.3rem}
  .logo-text{height:3.3rem}
  .logo b{background:linear-gradient(90deg,#fff,#f3b4c4);-webkit-background-clip:text;background-clip:text;color:transparent}
  @media (max-width:760px){.topbar{padding:.8rem 1rem}.logo-bird{height:2.6rem}.logo-text{height:2.6rem}}

  /* Hero */
  .hero{position:relative;height:74vh;min-height:26rem;max-height:62rem;padding:5rem 2rem 2.5rem calc(var(--side) + 2rem);display:flex;align-items:flex-end;overflow:hidden;background:linear-gradient(160deg,#112134,#01131d)}
  .hbg{position:absolute;inset:0;background-size:cover;background-position:center 20%;opacity:0;transition:opacity 1s ease;z-index:0}
  .hbg.on{opacity:1}
  .hero::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--bg) 0%,rgba(1,19,29,.75) 32%,transparent 70%),linear-gradient(0deg,var(--bg) 0%,transparent 40%);z-index:1}
  .hero-content{position:relative;z-index:2;max-width:36rem;transition:opacity .4s}
  .hero-content.fade{opacity:0}
  .brand-tag{font-size:.75rem;letter-spacing:.25em;color:var(--muted);margin-bottom:.6rem;text-transform:uppercase}
  .hero h1{font-size:clamp(2rem,4.8vw,3.8rem);line-height:1.02;font-weight:900;letter-spacing:-.02em;text-transform:uppercase;text-shadow:0 2px 20px rgba(0,0,0,.6)}
  .hmeta{display:flex;gap:.8rem;align-items:center;margin-top:.8rem;font-size:.9rem;color:#e6e6ef;flex-wrap:wrap}
  .hmeta .star{color:#facc15;font-weight:700}
  .hero p{margin:.9rem 0 1.3rem;color:#e6e6ef;line-height:1.5;font-size:1rem;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;text-shadow:0 1px 8px rgba(0,0,0,.7)}
  .btns{display:flex;gap:.75rem;flex-wrap:wrap}
  .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;padding:.75rem 1.6rem;border-radius:.4rem;border:0;font-size:1rem;font-weight:600;cursor:pointer;transition:transform .15s,filter .15s;font-family:inherit}
  .btn:hover{transform:translateY(-2px);filter:brightness(1.1)}
  .btn svg{width:1.1rem;height:1.1rem}
  .btn.play{background:#fff;color:#111}
  .btn.info{background:rgba(100,140,180,.55);color:#fff}
  .dots{position:absolute;right:2rem;bottom:1.6rem;z-index:3;display:flex;gap:.4rem}
  .dots span{width:.5rem;height:.5rem;border-radius:50%;background:rgba(255,255,255,.35);cursor:pointer;transition:all .3s}
  .dots span.on{background:#fff;width:1.4rem;border-radius:1rem}
  @media (max-width:760px){
    .hero{height:auto;min-height:30rem;padding:5rem 1.1rem 2.2rem}
    .hero::after{background:linear-gradient(0deg,var(--bg) 0%,rgba(1,19,29,.65) 55%,rgba(1,19,29,.15) 100%)}
    .hero p{font-size:.92rem;-webkit-line-clamp:3}
    .btn{padding:.7rem 1.2rem;flex:1}
    .dots{right:1rem;bottom:.8rem}
  }

  /* Filas */
  main{padding:0 0 2rem calc(var(--side) + 2rem);margin-top:-1rem;position:relative;z-index:3;min-height:30vh}
  @media (max-width:760px){main{padding:0 0 1rem 1rem;margin-top:0}}
  .row{margin-bottom:1.6rem;position:relative;scroll-margin-top:1rem}
  .row h2{font-size:1.15rem;margin-bottom:.7rem;font-weight:700}
  .strip{display:flex;gap:var(--gap);overflow-x:auto;padding:.5rem 2rem 1rem 0;scroll-behavior:smooth;scrollbar-width:none;scroll-snap-type:x proximity;-webkit-overflow-scrolling:touch}
  .strip::-webkit-scrollbar{display:none}
  .arrow{position:absolute;top:2.2rem;bottom:1rem;width:3rem;border:0;background:linear-gradient(90deg,rgba(1,19,29,.9),transparent);color:#fff;cursor:pointer;z-index:6;opacity:0;transition:opacity .2s;display:grid;place-items:center}
  .arrow.r{right:0;background:linear-gradient(270deg,rgba(1,19,29,.9),transparent)}
  .arrow.l{left:0}
  .row:hover .arrow{opacity:1}
  @media (hover:none){.arrow{display:none}}

  .card{flex:0 0 auto;width:var(--card-w);aspect-ratio:2/3;border-radius:.4rem;position:relative;overflow:hidden;cursor:pointer;transition:transform .25s,box-shadow .25s;scroll-snap-align:start;background:#112134}
  .card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .4s}
  .card img.ok{opacity:1}
  @media (hover:hover){.card:hover{transform:scale(1.08);z-index:5;box-shadow:0 .9rem 1.9rem rgba(0,0,0,.6)}}
  .card:active{transform:scale(.97)}
  .card .rate{position:absolute;top:.4rem;right:.4rem;z-index:3;background:rgba(0,0,0,.65);backdrop-filter:blur(4px);border-radius:.3rem;padding:.1rem .35rem;font-size:.68rem;font-weight:700;color:#facc15}
  .card .info{position:absolute;left:0;right:0;bottom:0;z-index:3;padding:1.4rem .6rem .6rem;background:linear-gradient(0deg,rgba(0,0,0,.95),transparent);opacity:0;transition:opacity .2s}
  @media (hover:hover){.card:hover .info{opacity:1}}
  .card.nop .info{opacity:1}
  .card .t{font-weight:800;font-size:.85rem;line-height:1.1}
  .card .sub{font-size:.66rem;color:#ffffffcc;margin-top:.2rem}
  .g0{background:linear-gradient(160deg,#ef4444,#7f1d1d)}.g1{background:linear-gradient(160deg,#475569,#0f172a)}
  .g2{background:linear-gradient(160deg,#f472b6,#831843)}.g3{background:linear-gradient(160deg,#0ea5e9,#082f49)}
  .g4{background:linear-gradient(160deg,#fbbf24,#78350f)}.g5{background:linear-gradient(160deg,#facc15,#a16207)}
  .g6{background:linear-gradient(160deg,#fb923c,#7c2d12)}.g7{background:linear-gradient(160deg,#e879f9,#4c1d95)}
  .g8{background:linear-gradient(160deg,#34d399,#064e3b)}.g9{background:linear-gradient(160deg,#a78bfa,#1e1b4b)}
  .g10{background:linear-gradient(160deg,#2dd4bf,#134e4a)}.g11{background:linear-gradient(160deg,#94a3b8,#1e293b)}

  .skel{flex:0 0 auto;width:var(--card-w);aspect-ratio:2/3;border-radius:.4rem;background:linear-gradient(110deg,#112134 30%,#183049 50%,#112134 70%);background-size:200% 100%;animation:sh 1.3s linear infinite}
  @keyframes sh{to{background-position:-200% 0}}
  .msg{color:var(--muted);padding:1.2rem 2rem 1.2rem 0;line-height:1.5}
  .msg b{color:#fff}

  /* Panel (búsqueda / mi lista) */
  .panel{position:fixed;inset:0;background:#01131d;z-index:45;display:none;flex-direction:column;padding:1.2rem 1.2rem 1.2rem calc(var(--side) + 1.2rem);overflow-y:auto}
  .panel.open{display:flex}
  html.lock,html.lock body{overflow:hidden;height:100%}
  /* Búsqueda: los resultados tienen su propio scroll vertical */
  .panel.search{overflow:hidden}
  .panel.search .sgrid{align-items:stretch;min-height:0}
  .panel.search .sres{display:flex;flex-direction:column;min-height:0}
  .panel.search .results{--sw:5.6rem;flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;scrollbar-width:thin;scrollbar-color:#2a4a68 transparent;padding-right:.3rem;align-content:start;position:relative;grid-template-columns:repeat(auto-fill,var(--sw));grid-auto-rows:calc(var(--sw) * 1.5);justify-content:start;gap:.5rem}
  .panel.search .skb{position:static;overflow:hidden}
  .panel.search .results .mas{text-align:center;padding:.8rem 0;font-size:.8rem}
  .panel.search .results::-webkit-scrollbar{width:6px}
  .panel.search .results::-webkit-scrollbar-thumb{background:#2a4a68;border-radius:3px}
  .panel.search .results::-webkit-scrollbar-thumb:hover{background:var(--accent)}
  .panel .bar{display:flex;gap:.7rem;align-items:center;margin-bottom:1.2rem}
  .panel input{flex:1;background:#112134;border:1px solid #1f3d5a;border-radius:.5rem;padding:.8rem 1rem;color:#fff;font-size:1.1rem;outline:none;font-family:inherit}
  .panel input:focus{border-color:var(--accent)}
  .panel h2{flex:1;font-size:1.4rem}
  .panel .x{background:none;border:0;color:#fff;font-size:1.5rem;cursor:pointer;padding:.3rem .7rem;margin-left:auto}
  .results{display:grid;grid-template-columns:repeat(auto-fill,minmax(var(--card-w),1fr));gap:var(--gap)}
  .results .card{width:100%}

  /* Búsqueda estilo Netflix: teclado a la izquierda, resultados a la derecha */
  .sgrid{display:flex;gap:1.4rem;align-items:flex-start;flex:1}
  .skb{flex:0 0 15.5rem;max-width:100%;position:sticky;top:0}
  .sres{flex:1;min-width:0}
  .sres h3{font-size:1.2rem;font-weight:800;margin-bottom:.9rem}
  .sbox{display:flex;align-items:center;gap:.5rem;background:#112134;border:1px solid #1f3d5a;border-radius:.6rem;padding:0 .7rem;margin-bottom:.6rem;transition:border-color .2s}
  .sbox:focus-within{border-color:var(--accent)}
  .sbox svg{flex:0 0 auto;color:var(--muted)}
  .panel .sbox input{border:0;background:transparent;padding:.6rem 0;font-size:.95rem;min-width:0}
  .keys{display:grid;grid-template-columns:repeat(8,1fr);gap:.2rem}
  .kbtns{display:grid;grid-template-columns:2fr 1fr 1fr;gap:.2rem;margin-top:.2rem}
  .skb button{background:#112134;border:1px solid #1d3a55;color:#fff;border-radius:.35rem;padding:.42rem 0;font-size:.78rem;font-weight:700;cursor:pointer;font-family:inherit;transition:background .15s,transform .1s,border-color .15s}
  .skb button:hover{background:var(--accent);border-color:var(--accent)}
  .skb button:active{transform:scale(.93)}
  .kbtns button{font-size:.68rem;letter-spacing:.02em}
  .panel.list .skb,.panel.list #sTitle{display:none}
  .panel.search .results .card{width:var(--sw);height:calc(var(--sw) * 1.5);aspect-ratio:auto}
  .panel.search .results .msg{grid-column:1/-1;grid-row:auto;height:auto}
  .panel.search .card .t{font-size:.7rem}
  .panel.search .card .sub{font-size:.58rem}
  .panel.search .card .rate{font-size:.58rem;top:.25rem;right:.25rem}
  @media (max-width:760px){.panel{padding:1rem 1rem calc(4.5rem + env(safe-area-inset-bottom))}
    .panel.search .results{--sw:4.6rem}
    .sgrid{flex-direction:column;align-items:stretch;gap:.6rem;width:100%}.sres{flex:none;width:100%}.panel.search .sres{flex:1}.skb{flex:none;position:static;width:100%}.keys,.kbtns{display:none}}

  /* Modal: ficha a pantalla completa (estilo Netflix) */
  .modal{position:fixed;inset:0;background:var(--panel);display:none;align-items:stretch;justify-content:stretch;z-index:60}
  .modal.open{display:flex}
  .box{background:var(--panel);width:100%;height:100%;overflow:auto;animation:fadeIn .25s ease;position:relative}
  @keyframes fadeIn{from{opacity:0}to{opacity:1}}
  .top{height:82vh;min-height:26rem;max-height:58rem;background-size:cover;background-position:center top;position:relative;display:flex;align-items:flex-end;padding:2rem 3rem 2.6rem;background-color:#112134}
  .top::before{content:"";position:absolute;inset:0;background:linear-gradient(0deg,var(--panel) 2%,rgba(1,19,29,.55) 40%,rgba(1,19,29,.15) 75%),linear-gradient(90deg,rgba(1,19,29,.75),transparent 60%)}
  .player{height:100vh;height:100dvh;background:#000;position:relative}
  .player iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
  .body{padding:1.4rem 3rem 3rem}
  .chips{display:flex;flex-wrap:wrap;gap:.5rem;margin-bottom:.9rem;font-size:.85rem;align-items:center}
  .chip{background:#183049;border-radius:2rem;padding:.2rem .7rem;color:#ddd}
  .chip.star{color:#facc15;font-weight:700}
  .body .lab{font-size:.78rem;color:#8a8a9a;text-transform:uppercase;letter-spacing:.12em;margin-bottom:.3rem}
  .body .cast{color:#ddd;font-size:.92rem;margin-bottom:1.1rem;line-height:1.4}
  .close{position:fixed;top:1rem;right:1.2rem;background:rgba(0,0,0,.6);border:0;color:#fff;width:2.6rem;height:2.6rem;border-radius:50%;cursor:pointer;z-index:20;font-size:1.1rem}
  .btn.list{background:rgba(100,140,180,.45);color:#fff}
  .btn.trl{background:rgba(100,140,180,.55);color:#fff}
  .btn.trl[disabled]{opacity:.45;cursor:default}
  .btn.trl[disabled]:hover{transform:none;filter:none}

  .box .tinfo{position:relative;z-index:2;max-width:42rem}
  .box .tinfo h3{font-size:clamp(1.8rem,4.5vw,3.6rem);line-height:1.02;text-transform:uppercase;font-weight:900;letter-spacing:-.02em;margin-bottom:.8rem;text-shadow:0 2px 20px rgba(0,0,0,.6)}
  .box .tinfo p{color:#e6e6ef;line-height:1.5;margin:0 0 1.2rem;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;text-shadow:0 1px 8px rgba(0,0,0,.7)}
  .box .tinfo .chips{margin-bottom:.8rem}
  .box .back{position:fixed;top:1rem;left:1.2rem;z-index:20;background:rgba(0,0,0,.6);border:0;color:#fff;border-radius:50%;width:2.8rem;height:2.8rem;padding:0;display:flex;align-items:center;justify-content:center;cursor:pointer;font-family:inherit}
  .box .back:hover{background:rgba(0,0,0,.85)}

  /* Episodios */
  .eps{margin-top:1.6rem}
  .ephead{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:.8rem;border-bottom:1px solid #1d3a55;padding-bottom:.8rem}
  .ephead h4{font-size:1.4rem;font-weight:800}
  .ephead select{background:#112134;color:#fff;border:1px solid #1f3d5a;border-radius:.4rem;padding:.55rem .9rem;font-size:.95rem;font-family:inherit;cursor:pointer;outline:none}
  .ep{display:flex;gap:1rem;align-items:center;padding:.9rem .8rem;border-radius:.5rem;cursor:pointer;transition:background .15s}
  .ep:hover{background:#183049}
  .ep .n{flex:0 0 2.2rem;text-align:center;font-size:1.4rem;color:#9a9aa8}
  .ep .still{flex:0 0 11rem;aspect-ratio:16/9;border-radius:.35rem;background:#112134 center/cover no-repeat;position:relative;display:grid;place-items:center}
  .ep .still svg{width:1.8rem;height:1.8rem;fill:#fff;stroke:none;opacity:0;transition:opacity .15s;filter:drop-shadow(0 1px 6px rgba(0,0,0,.8))}
  .ep:hover .still svg{opacity:1}
  .ep .still .pbar{position:absolute;left:0;right:0;bottom:0;height:.28rem;background:rgba(255,255,255,.28);border-radius:0 0 .35rem .35rem;overflow:hidden}
  .ep .still .pbar i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),var(--accent2));border-radius:0 .2rem .2rem 0}
  .ep .tx{flex:1;min-width:0}
  .ep .th{display:flex;justify-content:space-between;gap:1rem;font-weight:700;margin-bottom:.3rem}
  .ep .th span:last-child{color:#9a9aa8;font-weight:500;font-size:.9rem;white-space:nowrap}
  .ep .ov{color:var(--muted);font-size:.88rem;line-height:1.45;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
  @media (max-width:700px){
    .box .top{padding:1.4rem 1.1rem 1.6rem;height:70vh}
    .box .body{padding:1rem 1.1rem 3rem}
    .ep .still{flex-basis:7.2rem}.ep .n{flex-basis:1.4rem;font-size:1.1rem}.ep .ov{-webkit-line-clamp:2;font-size:.8rem}
  }
  .box .btns .btn.play{border-radius:.25rem;padding:.8rem 2.4rem;font-size:1.05rem;font-weight:700;letter-spacing:.01em}
  .box .btns .btn.play svg{width:1.3rem;height:1.3rem}
  .btn.list.on{background:var(--accent)}


  /* Reproductor propio (solo cinta de control, sin interfaz de YouTube) */
  .cp{background:#000;user-select:none;-webkit-user-select:none;overflow:hidden}
  .cp:fullscreen{width:100vw;height:100vh;aspect-ratio:auto;max-height:none}
  .cp:-webkit-full-screen{width:100vw;height:100vh;aspect-ratio:auto;max-height:none}
  .cp iframe{inset:auto;left:0;top:-30%;width:100%;height:160%}
  .cp .shield{position:absolute;inset:0;z-index:2;cursor:pointer}
  .cp .cover{position:absolute;inset:0;z-index:4;display:none;place-items:center;background:#01131d center/cover no-repeat}
  .cp .cover::before{content:"";position:absolute;inset:0;background:rgba(0,0,0,.6)}
  .cp .cover .btn{position:relative}
  .cp .cover.show{display:grid}
  .cp .ctrl{position:absolute;left:0;right:0;bottom:0;z-index:6;display:flex;align-items:center;gap:.6rem;padding:1.8rem .9rem .6rem;background:linear-gradient(0deg,rgba(0,0,0,.88),transparent);transition:opacity .3s}
  .cp.idle .ctrl{opacity:0}
  .cp.idle,.cp.idle .shield{cursor:none}
  .cp .ctrl button{background:none;border:0;color:#fff;cursor:pointer;padding:.25rem;display:grid;place-items:center}
  .cp .ctrl button:hover{color:var(--accent)}
  .cp .ctrl svg{width:1.35rem;height:1.35rem;fill:currentColor;stroke:none}
  .cp .tm{font-size:.78rem;color:#ddd;min-width:3.4rem;text-align:center;font-variant-numeric:tabular-nums}
  .cp input[type=range]{-webkit-appearance:none;appearance:none;background:transparent;height:1rem;cursor:pointer;flex:1;min-width:0;--p:0%}
  .cp input[type=range]::-webkit-slider-runnable-track{height:.28rem;border-radius:1rem;background:linear-gradient(90deg,var(--accent),var(--accent2) var(--p),rgba(255,255,255,.3) var(--p))}
  .cp input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:.85rem;height:.85rem;border-radius:50%;background:#fff;margin-top:-.28rem}
  .cp input[type=range]::-moz-range-track{height:.28rem;border-radius:1rem;background:rgba(255,255,255,.3)}
  .cp input[type=range]::-moz-range-progress{height:.28rem;border-radius:1rem;background:linear-gradient(90deg,var(--accent),var(--accent2))}
  .cp input[type=range]::-moz-range-thumb{width:.85rem;height:.85rem;border:0;border-radius:50%;background:#fff}
  .cp #cVol{flex:0 0 4.5rem}
  @media (max-width:600px){.cp #cVol{display:none}}
  /* Video propio (archivo directo): sin subtítulos nunca */
  .cp video{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000;z-index:1}
  .cp video.off{z-index:0;opacity:0;pointer-events:none}
  .cp .load{position:absolute;inset:0;z-index:3;display:none;place-items:center;pointer-events:none}
  .cp .load.show{display:grid}
  .cp .load i{width:3.2rem;height:3.2rem;border:.28rem solid rgba(255,255,255,.25);border-top-color:#fff;border-radius:50%;animation:cpgira .8s linear infinite}
  @keyframes cpgira{to{transform:rotate(360deg)}}
  .cp .big{position:absolute;inset:0;z-index:3;display:none;place-items:center;pointer-events:none}
  .cp .big.show{display:grid}
  .cp .big b{width:4.6rem;height:4.6rem;border-radius:50%;background:rgba(0,0,0,.6);display:grid;place-items:center}
  .cp .big svg{width:2rem;height:2rem;fill:#fff}
  .cp video::cue{display:none}
  .cp video::-webkit-media-text-track-container{display:none!important}
  /* Siguiente episodio: cuadro con círculo de 10 s */
  .cp .nx{position:absolute;right:1rem;bottom:4.6rem;z-index:7;display:none;align-items:center;gap:.8rem;padding:.65rem .8rem .65rem .7rem;background:rgba(1,19,29,.94);border:1px solid #1f3d5a;border-radius:.6rem;color:#fff;cursor:pointer;max-width:min(22rem,calc(100% - 2rem));box-shadow:0 .4rem 1.4rem rgba(0,0,0,.6)}
  .cp .nx.show{display:flex;animation:fadeIn .25s ease}
  .cp .nx:hover{background:#112134}
  .cp .nx .ring{position:relative;flex:0 0 auto;width:2.8rem;height:2.8rem}
  .cp .nx .ring svg{width:100%;height:100%;transform:rotate(-90deg);display:block}
  .cp .nx .ring circle{fill:none;stroke-width:3.4}
  .cp .nx .ring .bg{stroke:rgba(255,255,255,.2)}
  .cp .nx .ring .fg{stroke:var(--accent);stroke-linecap:round;stroke-dasharray:100.53;stroke-dashoffset:0;transition:stroke-dashoffset .12s linear}
  .cp .nx .num{position:absolute;inset:0;display:grid;place-items:center;font-weight:700;font-size:1.05rem;font-variant-numeric:tabular-nums}
  .cp .nx .tx{min-width:0}
  .cp .nx .tx small{display:block;color:var(--muted);font-size:.72rem;margin-bottom:.1rem}
  .cp .nx .tx b{display:block;font-size:.9rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .cp .nx .x{background:none;border:0;color:#b4c3d3;cursor:pointer;font-size:1rem;line-height:1;padding:.3rem;margin-left:.1rem;font-family:inherit}
  .cp .nx .x:hover{color:#fff}
  @media (max-width:600px){.cp .nx{right:.6rem;bottom:3.4rem;gap:.6rem;padding:.45rem .6rem .45rem .5rem}.cp .nx .ring{width:2.2rem;height:2.2rem}.cp .nx .num{font-size:.9rem}.cp .nx .tx b{font-size:.8rem}}
  /* contenedor que se conserva al pasar de episodio en pantalla completa */
  .fsw{background:#000}
  .fsw:fullscreen>.player,.fsw:-webkit-full-screen>.player,.fsw.pfs>.player{height:100%!important;aspect-ratio:auto!important;max-height:none!important}
  /* Celular en vertical: el reproductor mide lo que el video (16:9), sin franjas negras arriba y abajo */
  @media (max-width:760px) and (orientation:portrait){
    .player{height:auto;aspect-ratio:16/9;max-height:100dvh}
    .player.cp:fullscreen,.player.cp:-webkit-full-screen{height:100%;aspect-ratio:auto;max-height:none}
  }
  /* Pantalla completa simulada (sin API) */
  .cp.pfs{position:fixed;left:0;top:0;width:100vw;height:100vh;height:100dvh;z-index:99999;aspect-ratio:auto;max-height:none}
  /* Celular en vertical dentro de pantalla completa: se gira 90° para verse horizontal */
  .cp.rot:fullscreen,.cp.rot:-webkit-full-screen,.cp.pfs.rot{
    position:fixed!important;left:0!important;top:0!important;
    width:100vh!important;height:100vw!important;aspect-ratio:auto!important;max-height:none!important;
    transform-origin:0 0;transform:translateX(100vw) rotate(90deg)}
  .cp.pfs.rot{width:100dvh!important}
  html.pfs-on,html.pfs-on body{overflow:hidden}
  /* ===== Celular: pausa al centro, dos círculos ±10 s y barra fácil de tocar ===== */
  .cp .mc{display:none}
  @media (pointer:coarse){
    .cp .mc{position:absolute;inset:0;z-index:6;display:flex;align-items:center;justify-content:center;gap:2.2rem;pointer-events:none;transition:opacity .3s}
    .cp .mc button{pointer-events:auto;border:0;color:#fff;background:none;border-radius:50%;display:grid;place-items:center;padding:0;cursor:pointer;-webkit-tap-highlight-color:transparent;touch-action:manipulation}
    .cp .mc .sk{width:3.4rem;height:3.4rem}
    .cp .mc button svg{filter:drop-shadow(0 0 3px rgba(0,0,0,.85))}
    .cp .mc .sk svg{width:3rem;height:3rem}
    .cp .mc .mp{width:4.6rem;height:4.6rem}
    .cp .mc .mp svg{width:3.2rem;height:3.2rem;fill:url(#gpGrad);stroke:none}
    .cp .mc .mp .ip{display:none}
    .cp.paused .mc .mp .ip{display:block}
    .cp.paused .mc .mp .ia{display:none}
    .cp .load.show ~ .mc .mp{visibility:hidden}
    .cp.idle .mc,.cp.idle .ctrl{opacity:0;pointer-events:none}
    .cp.idle .mc button,.cp.idle .ctrl *{pointer-events:none}
    .cp #cPlay,.cp .big{display:none!important}
    .cp .ctrl{padding-top:2.4rem}
    .cp input[type=range]{height:2.6rem;touch-action:none}
    .cp input[type=range]::-webkit-slider-runnable-track{height:.36rem}
    .cp input[type=range]::-webkit-slider-thumb{width:1.15rem;height:1.15rem;margin-top:-.4rem}
    .cp input[type=range]::-moz-range-track{height:.36rem}
    .cp input[type=range]::-moz-range-progress{height:.36rem}
    .cp input[type=range]::-moz-range-thumb{width:1.15rem;height:1.15rem}
    .cp .nx{bottom:5rem}
    .cp .shield{touch-action:none}
    .cp.br video,.cp.br iframe{filter:brightness(var(--br,1))}
    .cp .gh{position:absolute;top:50%;transform:translateY(-50%);z-index:8;display:flex;flex-direction:column;align-items:center;gap:.5rem;opacity:0;pointer-events:none;transition:opacity .25s;filter:drop-shadow(0 0 3px rgba(0,0,0,.85))}
    .cp .gh.show{opacity:1}
    .cp .gh.izq{left:9%}
    .cp .gh.der{right:9%}
    .cp .gh .ic svg{width:1.9rem;height:1.9rem;display:block}
    .cp .gh .tr{position:relative;width:.4rem;height:7rem;border-radius:1rem;background:rgba(255,255,255,.35);overflow:hidden}
    .cp .gh .tr b{position:absolute;left:0;right:0;bottom:0;background:linear-gradient(0deg,var(--accent2),var(--accent))}
    .cp .gh span{font-size:.8rem;color:#fff;font-variant-numeric:tabular-nums}
  }
  /* Celular en horizontal (y en pantalla completa): el video llena toda la pantalla, sin franjas negras a los lados */
  @media (pointer:coarse) and (orientation:landscape) and (max-height:520px){
    .cp video{object-fit:cover}
  }
  @media (pointer:coarse) and (orientation:landscape){
    .cp:fullscreen video,.cp:-webkit-full-screen video{object-fit:cover}
  }

  footer{padding:2rem 2rem 2rem calc(var(--side) + 2rem);color:#6d6d7c;font-size:.78rem;line-height:1.5}
  @media (max-width:760px){footer{padding:1rem}}

  /* ============================================================
     ADAPTACIÓN A CUALQUIER PANTALLA
     (móviles pequeños, móviles normales, horizontal, tablets, PC, TV)
     Las pantallas grandes escalan solas con el rem de arriba (hasta 5000px).
     ============================================================ */
  html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
  /* Sin zoom con los dedos (pellizco ni doble toque); el desplazamiento sigue normal */
  html,body{touch-action:pan-x pan-y}

  html,body{overscroll-behavior-x:none}
  img,video,canvas{max-width:100%}
  .box,.panel{-webkit-overflow-scrolling:touch}

  /* Alturas que no "saltan" cuando aparece/desaparece la barra del navegador móvil */
  @supports (height:1dvh){
    .hero{height:74dvh}
    .top{height:82dvh}
  }
  @media (max-width:700px){
    @supports (height:1dvh){.box .top{height:70dvh}}
  }

  /* Tablets y pantallas medianas */
  @media (min-width:761px) and (max-width:1100px){
    :root{--card-w:9.4rem}
    .hero{padding-right:2rem}
    .top{padding:2rem 2rem 2.2rem}
    .body{padding:1.4rem 2rem 3rem}
    .ep .still{flex-basis:9rem}
  }

  /* Móviles pequeños (≤ 380px) */
  @media (max-width:380px){
    :root{--card-w:6.9rem;--gap:.45rem}
    .logo-bird,.logo-text{height:2.2rem}
    .hero{min-height:27rem;padding:4.6rem .9rem 2rem}
    .hero h1{font-size:1.75rem}
    .hmeta{font-size:.8rem;gap:.5rem}
    .btns{gap:.5rem}
    .btn{padding:.65rem .8rem;font-size:.9rem}
    .box .top{padding:1.2rem .9rem 1.4rem}
    .box .body{padding:.9rem .9rem 3rem}
    .box .tinfo h3{font-size:1.7rem}
    .box .btns .btn.play{padding:.75rem 1.4rem;font-size:.95rem}
    .ephead{flex-wrap:wrap}.ephead h4{font-size:1.15rem}
    .ep{gap:.6rem;padding:.7rem .4rem}
    .ep .still{flex-basis:6rem}
    .ep .th{flex-direction:column;gap:.1rem}
    .row h2{font-size:1rem}
    .panel.search .results{--sw:4.1rem}
  }
  @media (max-width:340px){
    html{font-size:14.5px}
    :root{--card-w:6.3rem}
  }

  /* Móviles / tablets en horizontal (poca altura) */
  @media (orientation:landscape) and (max-height:520px){
    .hero{height:auto;min-height:0;max-height:none;padding-top:4.2rem;padding-bottom:1.6rem}
    .hero h1{font-size:clamp(1.5rem,5vh,2.4rem)}
    .hero p{-webkit-line-clamp:2;margin:.5rem 0 .8rem;font-size:.85rem}
    .top,.box .top{height:auto;min-height:0;max-height:none;padding-top:4rem;padding-bottom:1.4rem}
    .box .tinfo h3{font-size:clamp(1.4rem,6vh,2.4rem)}
    .box .tinfo p{-webkit-line-clamp:2;margin-bottom:.8rem}
    .sidebar{gap:.5rem;justify-content:flex-start;overflow-y:auto;padding:.8rem 0}
    .topbar{padding-top:.5rem;padding-bottom:.5rem}
    .logo-bird,.logo-text{height:2.2rem}
    .btn{padding:.55rem 1.1rem}
    .box .btns .btn.play{padding:.6rem 1.6rem}
    /* respetar la muesca / bordes redondeados a los lados */
    main,.hero,.panel,.box .top,.box .body{padding-left:max(1rem,env(safe-area-inset-left));padding-right:max(1rem,env(safe-area-inset-right))}
    .close{right:max(1.2rem,env(safe-area-inset-right))}
    .box .back{left:max(1.2rem,env(safe-area-inset-left))}
  }
  @media (orientation:landscape) and (max-height:520px) and (min-width:761px){
    .hero,main,.panel{padding-left:calc(var(--side) + 1.2rem)}
  }
  /* Barra inferior en móvil horizontal estrecho (≤760px de ancho): más baja */
  @media (max-width:760px) and (orientation:landscape){
    .sidebar{height:calc(2.9rem + env(safe-area-inset-bottom));overflow:visible}
    body{padding-bottom:calc(3.2rem + env(safe-area-inset-bottom))}
  }

  /* Pantallas táctiles: botones más fáciles de tocar */
  @media (pointer:coarse){
    .btn{min-height:2.75rem}
    .sidebar button{min-width:2.9rem;min-height:2.9rem}
    .close{width:3rem;height:3rem}
    .box .back{width:3rem;height:3rem}
    .ephead select{min-height:2.75rem}
  }

  /* Pantallas muy anchas (ultrapanorámicas / TV): que el texto no se estire sin fin */
  @media (min-aspect-ratio:21/9){
    .hero{max-height:78dvh}
    .hero-content{max-width:42rem}
  }
  @media (min-width:1920px){
    .box .tinfo{max-width:52rem}
    .body{max-width:100rem}
  }

  /* TV / mando a distancia / teclado: se ve claramente qué está seleccionado */
  :focus{outline:none}
  :focus-visible{outline:.2rem solid #fff;outline-offset:.2rem;border-radius:.4rem}
  .card:focus-visible{transform:scale(1.08);z-index:5;box-shadow:0 .9rem 1.9rem rgba(0,0,0,.6)}
  .card:focus-visible .info{opacity:1}
  .ep:focus-visible{background:#183049}
  .ep:focus-visible .still svg{opacity:1}
  .btn:focus-visible{transform:translateY(-2px);filter:brightness(1.1)}
  .sidebar button:focus-visible{color:#fff;transform:scale(1.15)}
  .row:focus-within .arrow{opacity:1}

  /* Respeta a quien desactiva las animaciones en su dispositivo */
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}
  }
</style>
</head>
<body>

<nav class="sidebar" id="nav">
  <button title="Buscar" data-go="search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg></button>
  <button title="Inicio" data-go="home" class="active"><svg viewBox="0 0 24 24"><path d="M3 11l9-8 9 8"/><path d="M5 10v10h5v-6h4v6h5V10"/></svg></button>
  <button title="Próximamente" data-go="upcoming"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg></button>
  <button title="Series" data-go="tv"><svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/></svg></button>
  <button title="En cartelera" data-go="nowplaying"><svg viewBox="0 0 24 24"><rect x="3" y="7" width="18" height="14" rx="2"/><path d="M3 7l3-4 4 4 4-4 4 4 3-4M3 12h18"/></svg></button>
  <button title="Mi lista" data-go="list"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg></button>
</nav>


<header class="hero" id="hero">
  <div class="hbg" id="bgA"></div><div class="hbg" id="bgB"></div>
  <div class="hero-content" id="hc">
    <div class="brand-tag" id="hTag">GipaPlay</div>
    <h1 id="hTitle"></h1>
    <div class="hmeta" id="hMeta"></div>
    <p id="hOver"></p>
    <div class="btns">
      <button class="btn play" id="hPlay"><svg viewBox="0 0 24 24" style="fill:currentColor;stroke:none"><path d="M6 4l14 8-14 8z"/></svg> Reproducir</button>
      <button class="btn info" id="hInfo">Más información</button>
    </div>
  </div>
  <div class="dots" id="dots"></div>
</header>

<main id="rows"></main>

<footer>
  Datos e imágenes de películas: TMDB. This product uses the TMDB API but is not endorsed or certified by TMDB.<br>
  GipaPlay · Proyecto de demostración.
</footer>

<div class="panel" id="panel">
  <div class="bar">
    <h2 id="pTitle" style="display:none"></h2>
    <button class="x" id="pClose" aria-label="Cerrar">✕</button>
  </div>
  <div class="sgrid">
    <aside class="skb" id="skb">
      <div class="sbox">
        <svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>
        <input id="q" type="search" placeholder="Busca películas o series…" autocomplete="off">
      </div>
      <div class="keys" id="keys"></div>
      <div class="kbtns">
        <button type="button" data-a="space">Espacio</button>
        <button type="button" data-a="del" aria-label="Borrar">⌫</button>
        <button type="button" data-a="clear">Limpiar</button>
      </div>
    </aside>
    <section class="sres">
      <h3 id="sTitle"></h3>
      <div class="results" id="results"></div>
    </section>
  </div>
</div>

<div class="modal" id="modal"><div class="box" id="box"></div></div>

<script>
/* Pantalla completa: en celular la película siempre se ve en horizontal.
   1) Intenta bloquear la orientación; 2) si el celular sigue en vertical, gira el reproductor por CSS. */
let __fsEl = null;
function __fsActivo(){ return document.fullscreenElement || document.webkitFullscreenElement || (__fsEl && __fsEl.classList.contains('pfs') ? __fsEl : null); }
function __fsRotar(){
  if(!__fsEl) return;
  const activo = __fsActivo();
  if(!activo){ __fsEl.classList.remove('rot','pfs'); __fsEl = null; return; }
  const vertical = innerHeight > innerWidth;
  __fsEl.classList.toggle('rot', vertical);
}
function __fsSalir(){
  try{ screen.orientation && screen.orientation.unlock && screen.orientation.unlock(); }catch(e){}
  if(__fsEl){ __fsEl.classList.remove('rot','pfs'); }
  document.documentElement.classList.remove('pfs-on');
  const ex = document.exitFullscreen || document.webkitExitFullscreen;
  if(document.fullscreenElement || document.webkitFullscreenElement) ex.call(document);
  __fsEl = null;
}
function pantallaCompletaHorizontal(el, video){
  if(__fsActivo()){ __fsSalir(); return; }
  __fsEl = el;
  const bloquear = () => {
    try{
      if(screen.orientation && screen.orientation.lock){
        const p = screen.orientation.lock('landscape');
        if(p && p.catch) p.catch(()=>{});
      }
    }catch(e){}
    setTimeout(__fsRotar, 250);
    setTimeout(__fsRotar, 700);
  };
  const req = el.requestFullscreen || el.webkitRequestFullscreen;
  if(req){
    let r;
    try{ r = req.call(el, {navigationUI:'hide'}); }catch(e){ try{ r = req.call(el); }catch(e2){ r = null; } }
    if(r && r.then) r.then(bloquear).catch(() => { el.classList.add('pfs'); document.documentElement.classList.add('pfs-on'); __fsRotar(); });
    else { bloquear(); __fsRotar(); }
  } else if(video && video.webkitEnterFullscreen){
    /* iPhone: el reproductor nativo ya gira solo a horizontal */
    __fsEl = null;
    video.webkitEnterFullscreen();
  } else {
    /* Sin API de pantalla completa: se simula cubriendo toda la pantalla */
    el.classList.add('pfs'); document.documentElement.classList.add('pfs-on');
    __fsRotar();
  }
}
['fullscreenchange','webkitfullscreenchange'].forEach(ev => document.addEventListener(ev, () => {
  if(!(document.fullscreenElement || document.webkitFullscreenElement) && !(__fsEl && __fsEl.classList.contains('pfs'))){
    try{ screen.orientation && screen.orientation.unlock && screen.orientation.unlock(); }catch(e){}
    if(__fsEl){ __fsEl.classList.remove('rot'); __fsEl = null; }
  } else __fsRotar();
}));
addEventListener('resize', __fsRotar);
addEventListener('orientationchange', () => setTimeout(__fsRotar, 150));
/* Controles táctiles del celular: pausa al centro, círculos ±10 s y toque en el video para mostrar/ocultar la cinta */
const SK_ATRAS = '<svg viewBox="0 0 24 24"><path d="M12 5A8 8 0 1 1 5.07 9" fill="none" stroke="url(#gpGrad)" stroke-width="2.2" stroke-linecap="round"/><path d="M12.8 1.9v6.2L8.4 5z" fill="url(#gpGrad)" stroke="url(#gpGrad)" stroke-width="1" stroke-linejoin="round"/><text x="12" y="16" text-anchor="middle" font-size="7.2" font-weight="700" font-family="sans-serif" fill="url(#gpGrad)" stroke="none">10</text></svg>';
const SK_ADEL = '<svg viewBox="0 0 24 24"><path d="M12 5A8 8 0 1 0 18.93 9" fill="none" stroke="url(#gpGrad)" stroke-width="2.2" stroke-linecap="round"/><path d="M11.2 1.9v6.2L15.6 5z" fill="url(#gpGrad)" stroke="url(#gpGrad)" stroke-width="1" stroke-linejoin="round"/><text x="12" y="16" text-anchor="middle" font-size="7.2" font-weight="700" font-family="sans-serif" fill="url(#gpGrad)" stroke="none">10</text></svg>';
function centroMovil(cp, o){
  if(!matchMedia('(pointer:coarse)').matches) return;
  if(!document.getElementById('gpGrad')) document.body.insertAdjacentHTML('beforeend',
    '<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs><linearGradient id="gpGrad" x1="0" y1="0" x2="1" y2="0"><stop offset="0" style="stop-color:var(--accent)"/><stop offset="1" style="stop-color:var(--accent2)"/></linearGradient></defs></svg>');
  const mc = document.createElement('div');
  mc.className = 'mc';
  mc.innerHTML = '<button class="sk" aria-label="Retroceder 10 segundos">' + SK_ATRAS + '</button>' +
    '<button class="mp" aria-label="Reproducir o pausar"><span class="ia">' + IC.pause + '</span><span class="ip">' + IC.play + '</span></button>' +
    '<button class="sk" aria-label="Adelantar 10 segundos">' + SK_ADEL + '</button>';
  const sh = cp.querySelector('.shield');
  sh.after(mc);
  const [atras, medio, adel] = mc.querySelectorAll('button');
  atras.onclick = () => { o.saltar(-10); o.wake(); };
  adel.onclick = () => { o.saltar(10); o.wake(); };
  medio.onclick = () => { o.toggle(); o.wake(); };
  /* un toque en el video muestra u oculta los controles (la pausa ahora está en el centro) */
  let estabaOculto = false;
  cp.addEventListener('touchstart', () => { estabaOculto = cp.classList.contains('idle'); }, {capture:true, passive:true});
  let gesto = false;
  sh.onclick = () => {
    if(gesto) return;                                        /* fue un deslizamiento, no un toque */
    if(estabaOculto){ estabaOculto = false; return; }       /* el toque ya los mostró */
    if(o.reproduciendo()) cp.classList.add('idle'); else o.wake();
  };

  /* ---- gestos en los costados: izquierda = brillo, derecha = volumen (deslizar el dedo hacia arriba o abajo) ---- */
  const volIn = cp.querySelector('#cVol');
  const ICO_SOL = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4.2" fill="url(#gpGrad)"/><path d="M12 2.5v2.6M12 18.9v2.6M2.5 12h2.6M18.9 12h2.6M5.3 5.3l1.8 1.8M16.9 16.9l1.8 1.8M5.3 18.7l1.8-1.8M16.9 7.1l1.8-1.8" fill="none" stroke="url(#gpGrad)" stroke-width="2" stroke-linecap="round"/></svg>';
  const ICO_VOL = '<svg viewBox="0 0 24 24"><path d="M3 9.5v5h3.6L11.5 19V5L6.6 9.5z" fill="url(#gpGrad)"/><path d="M14.5 8.5a4.8 4.8 0 0 1 0 7M17 6a8.2 8.2 0 0 1 0 12" fill="none" stroke="url(#gpGrad)" stroke-width="1.8" stroke-linecap="round"/></svg>';
  const hud = document.createElement('div');
  hud.className = 'gh';
  hud.innerHTML = '<i class="ic"></i><div class="tr"><b></b></div><span></span>';
  cp.appendChild(hud);
  let hudT = 0;
  const mostrar = (lado, ico, frac) => {
    hud.className = 'gh show ' + lado;
    hud.querySelector('.ic').innerHTML = ico;
    hud.querySelector('b').style.height = Math.round(frac * 100) + '%';
    hud.querySelector('span').textContent = Math.round(frac * 100) + '%';
    clearTimeout(hudT); hudT = setTimeout(() => hud.classList.remove('show'), 800);
  };
  let nivelBr = 0.5;                                         /* 0.5 = brillo normal del video */
  /* En la APK se usa el brillo real del dispositivo (sin filtro sobre el video); en el navegador se mantiene el filtro. */
  const enApk = !!window.AndroidControls;
  const aplicarBr = n => {
    nivelBr = n;
    if(enApk) return;
    cp.style.setProperty('--br', (0.3 + 1.4 * n).toFixed(3));
    cp.classList.add('br');
  };
  const brDispositivo = () => {
    try{ if(enApk && window.AndroidControls.getBrightness) return window.AndroidControls.getBrightness() / 100; }catch(e){}
    return nivelBr;
  };
  if(!enApk){ try{ const g0 = parseFloat(localStorage.getItem('gp_brillo')); if(isFinite(g0) && g0 >= 0 && g0 <= 1 && g0 !== 0.5) aplicarBr(g0); }catch(e){} }
  const ponerBrillo = n => {
    aplicarBr(n);
    try{ localStorage.setItem('gp_brillo', String(n)); }catch(e){}
    // Mantiene el gesto y el HUD originales; en la APK también ajusta el brillo Android.
    try{ if(window.AndroidControls) window.AndroidControls.setBrightness(Math.round(n * 100)); }catch(e){}
    mostrar('izq', ICO_SOL, n);
  };
  const ponerVolumen = n => {
    volIn.value = Math.round(n * 100);
    volIn.oninput();
    // Mantiene el gesto y el HUD originales; en la APK también ajusta el volumen Android.
    try{ if(window.AndroidControls) window.AndroidControls.setVolume(Math.round(n * 100)); }catch(e){}
    mostrar('der', ICO_VOL, n);
  };
  const rotado = () => cp.classList.contains('rot');
  const pos = t => {                                         /* posición del dedo en el sistema del reproductor (aunque esté girado) */
    const r = cp.getBoundingClientRect();
    return rotado()
      ? {x: (t.clientY - r.top) / r.height, y: (r.right - t.clientX) / r.width, h: r.width}
      : {x: (t.clientX - r.left) / r.width, y: (t.clientY - r.top) / r.height, h: r.height};
  };
  let g = null;
  sh.addEventListener('touchstart', e => {
    if(e.touches.length !== 1){ g = null; return; }
    const t = e.touches[0], p = pos(t);
    const lado = p.x < 0.33 ? 'izq' : p.x > 0.67 ? 'der' : null;
    g = lado ? {lado, X: t.clientX, Y: t.clientY, y0: p.y, h: p.h, activo: false,
                base: lado === 'izq' ? brDispositivo() : Math.min(1, (+volIn.value || 0) / 100)} : null;
  }, {passive: true});
  sh.addEventListener('touchmove', e => {
    if(!g) return;
    const t = e.touches[0];
    if(!g.activo){
      const dx = Math.abs(t.clientX - g.X), dY = Math.abs(t.clientY - g.Y);
      if(Math.hypot(dx, dY) < 10) return;
      if(!(rotado() ? dx > dY : dY > dx)){ g = null; return; }   /* deslizamiento horizontal: no es un gesto */
      g.activo = true; gesto = true;
      if(estabaOculto) cp.classList.add('idle');             /* mientras se desliza no se muestran los controles */
    }
    e.preventDefault();
    const dy = (pos(t).y - g.y0) * g.h;
    const n = Math.max(0, Math.min(1, g.base - dy / Math.min(260, g.h * 0.9)));
    if(g.lado === 'izq') ponerBrillo(n); else ponerVolumen(n);
  }, {passive: false});
  const finGesto = () => { g = null; setTimeout(() => { gesto = false; }, 350); };
  sh.addEventListener('touchend', finGesto);
  sh.addEventListener('touchcancel', finGesto);
}
</script>
<script>
/* ========= CONFIGURACIÓN ========= */
const API_KEY = 'bc517400d205c8850741c90a630df6ac';
const LANG    = 'es-MX';
const REGION  = 'PE';          // país para "en cartelera" y "próximamente"
/* Opcional: clave de YouTube Data API v3. Con ella se buscan en YouTube los tráilers doblados
   al español latino cuando TMDB solo tiene el original. Déjala vacía para desactivarlo. */
const YT_API_KEY = 'AIzaSyBacZ5nwMXT9rEAoa1R40t2n71PQKXAq1s';
/* Fuente de video del botón "Reproducir": se lee de la API (peliculas.json / animes.json / series.json).
   "url" puede ser un enlace o un arreglo con las partes del video en orden (se reproducen como una sola película). */
const VIDEOS_BASE = 'https://raw.githubusercontent.com/Saulcreen/api-videos/main/';
const VIDEOS_ARCHIVOS = ['animes.json', 'peliculas.json', 'series.json'];   /* agrega aquí más archivos si divides la API otra vez */
let VIDEOS = [];
/* Se descargan todos los archivos de la API y se juntan en una sola lista (sin caché para ver los cambios al instante).
   Si uno falla, los demás se cargan igual. */
/* estado.json lo escribe el bot de api-videos: trae la duración de cada parte, para no medirlas al reproducir */
let DURACIONES_API = {};
const ESTADO_LISTO = fetch(VIDEOS_BASE + 'estado.json?t=' + Date.now(), {cache:'no-store'})
  .then(r => r.ok ? r.json() : null)
  .then(d => { if(d && d.duraciones && typeof d.duraciones === 'object') DURACIONES_API = d.duraciones; })
  .catch(() => {});
/* outros.json (opcional): por tmdbId, cuánto dura el final contado desde el fin del episodio. Ej.: {"13916": 90, "255752": "1:47"}
   (si el valor pasa de 10 min se toma como el minuto exacto donde empieza el outro).
   Para un minuto distinto por episodio: {"255752": {"1x1": "23:10", "1x2": "22:52", "*": "23:00"}}  ("*" = los demás) */
let OUTROS_API = {};
const OUTROS_LISTO = fetch(VIDEOS_BASE + 'outros.json?t=' + Date.now(), {cache:'no-store'})
  .then(r => r.ok ? r.text() : null)
  .then(t => t ? JSON.parse(t.replace(/,(\s*[}\]])/g, '$1')) : null)   /* tolera una coma de más antes de } o ] */
  .then(d => { if(d && typeof d === 'object' && !Array.isArray(d)) OUTROS_API = d; })
  .catch(() => {});
const VIDEOS_LISTO = Promise.all(VIDEOS_ARCHIVOS.map(n =>
  fetch(VIDEOS_BASE + n + '?t=' + Date.now(), {cache:'no-store'})
    .then(r => { if(!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
    .then(d => Array.isArray(d) ? d : [])
    .catch(e => { console.warn('GipaPlay · no se pudo cargar ' + n + ':', e); return []; })
)).then(async listas => { VIDEOS = listas.flat(); await Promise.all([ESTADO_LISTO, OUTROS_LISTO]); });
/* Busca en la API el video que corresponde a la película o episodio elegido */
/* url puede ser un texto o un arreglo con las partes del video, en orden */
const urlOk = u => typeof u === 'string' ? /^https?:\/\//i.test(u) : Array.isArray(u) && u.length > 0 && u.every(x => typeof x === 'string' && /^https?:\/\//i.test(x));
const FUENTE_PELICULA = (it, ep) => {
  const mios = VIDEOS.filter(v => +v.tmdbId === it.id);
  const v = ep
    ? mios.find(x => +x.temporada === ep.season && +x.episodio === ep.episode)
    : (mios.find(x => !x.temporada && !x.episodio) || mios[0]);
  if(!v || !urlOk(v.url)) return null;
  return Array.isArray(v.url) && v.url.length === 1 ? v.url[0] : v.url;   /* arreglo = video en varias partes */
};
const API     = 'https://api.themoviedb.org/3';
const IMG     = 'https://image.tmdb.org/t/p/';
const BIG     = window.innerWidth > 1900;
const POSTER  = IMG + (BIG ? 'w500' : 'w342');
const BACK    = IMG + (window.innerWidth > 1400 ? 'original' : 'w1280');

/* ========= UTILIDADES ========= */
async function tmdb(path, params = {}){
  const u = new URL(API + path);
  u.searchParams.set('api_key', API_KEY);
  u.searchParams.set('language', LANG);
  for(const [k,v] of Object.entries(params)) u.searchParams.set(k, v);
  const r = await fetch(u);
  if(!r.ok) throw new Error('TMDB ' + r.status);
  return r.json();
}
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
/* Títulos que se muestran distinto al de TMDB (la gente los conoce así). Formato: 'tipo' + id de TMDB */
const TITULOS_PROPIOS = {'movie475557':'Joker'};   /* Guasón (2019) → Joker */
function norm(x, type){
  const t = type || x.media_type || 'movie';
  return {
    id:x.id, type:t,
    title:TITULOS_PROPIOS[t + x.id] || x.title || x.name || 'Sin título',
    year:(x.release_date || x.first_air_date || '').slice(0,4),
    poster:x.poster_path, backdrop:x.backdrop_path,
    overview:x.overview || '', rating:x.vote_average || 0,
    c:'g' + (x.id % 12)
  };
}
const tipoTxt = t => t === 'tv' ? 'Serie' : 'Película';

/* ========= MI LISTA (guardada en el navegador) ========= */
let memList = [];
function getList(){
  let l;
  try{ l = JSON.parse(localStorage.getItem('gipaplay_list') || '[]'); }catch(e){ l = memList; }
  return l.map(x => TITULOS_PROPIOS[x.type + x.id] ? {...x, title:TITULOS_PROPIOS[x.type + x.id]} : x);   /* títulos propios también en Mi lista */
}
function saveList(l){
  memList = l;
  try{ localStorage.setItem('gipaplay_list', JSON.stringify(l)); }catch(e){}
}
const enLista = it => getList().some(x => x.id === it.id && x.type === it.type);
function toggleLista(it){
  let l = getList();
  if(enLista(it)) l = l.filter(x => !(x.id === it.id && x.type === it.type));
  else l.unshift({id:it.id, type:it.type, title:it.title, year:it.year, poster:it.poster, backdrop:it.backdrop, overview:it.overview, rating:it.rating, c:it.c});
  saveList(l);
}

/* ========= TARJETAS ========= */
const _portadas = {};
/* Si TMDB no trae portada (o falla al cargar), pide la lista de imágenes de la película y toma un póster en español, inglés o el que haya */
async function portadaAlterna(it){
  const k = it.type + it.id;
  if(k in _portadas) return _portadas[k];
  try{ const c = localStorage.getItem('gipaplay_pt_' + k); if(c !== null) return (_portadas[k] = c || null); }catch(e){}
  let p = null;
  try{
    const d = await tmdb(`/${it.type}/${it.id}/images`, {language:'es', include_image_language:'es,en,null'});
    const ps = d.posters || [];
    const pick = ps.find(x => x.iso_639_1 === 'es') || ps.find(x => x.iso_639_1 === 'en') || ps[0];
    p = pick ? pick.file_path : null;
    try{ localStorage.setItem('gipaplay_pt_' + k, p || ''); }catch(e){}
  }catch(e){ return null; }          /* error de red: no se guarda, se reintenta otro día */
  return (_portadas[k] = p);
}
/* Series cuyo póster principal en TMDB es el de otra temporada: se usa el póster de la temporada indicada.
   "Cyberpunk: Edgerunners" (id 105248) trae ahora el arte de la temporada 2; aquí se usa el de la temporada 1. */
const PORTADA_TEMPORADA = {tv105248: 1};
async function portadaTemporada(it, n){
  const k = it.type + it.id + 's' + n;
  if(k in _portadas) return _portadas[k];
  try{ const c = localStorage.getItem('gipaplay_ps_' + k); if(c) return (_portadas[k] = c); }catch(e){}
  try{
    const d = await tmdb(`/${it.type}/${it.id}/season/${n}`);
    if(!d.poster_path) return null;
    try{ localStorage.setItem('gipaplay_ps_' + k, d.poster_path); }catch(e){}
    return (_portadas[k] = d.poster_path);
  }catch(e){ return null; }
}
/* Películas cuyo cartel debe verse en inglés (el cartel en español dice "Guasón"; aquí se muestra el que dice "Joker") */
const PORTADA_IDIOMA = {movie475557:'en'};
async function portadaIdioma(it, lang){
  const k = it.type + it.id + 'l' + lang;
  if(k in _portadas) return _portadas[k];
  try{ const c = localStorage.getItem('gipaplay_pi_' + k); if(c) return (_portadas[k] = c); }catch(e){}
  try{
    const d = await tmdb(`/${it.type}/${it.id}/images`, {language:lang, include_image_language:lang});
    const ps = (d.posters || []).filter(x => x.iso_639_1 === lang).sort((a, b) => (b.vote_average || 0) - (a.vote_average || 0));
    if(!ps.length) return null;
    try{ localStorage.setItem('gipaplay_pi_' + k, ps[0].file_path); }catch(e){}
    return (_portadas[k] = ps[0].file_path);
  }catch(e){ return null; }
}
function crearCard(it){
  const el = document.createElement('div');
  el.className = 'card ' + it.c + (it.poster ? '' : ' nop');
  el.innerHTML =
    (it.rating ? `<div class="rate">★ ${it.rating.toFixed(1)}</div>` : '') +
    `<div class="info"><div class="t">${esc(it.title)}</div><div class="sub">${tipoTxt(it.type)}${it.year ? ' · ' + it.year : ''}</div></div>`;
  let etapa = 0;
  const poner = src => {
    let img = el.querySelector('img');
    if(!img){ img = document.createElement('img'); img.alt = it.title; img.loading = 'lazy'; el.prepend(img); }
    img.classList.remove('ok');
    img.onload = () => { img.classList.add('ok'); el.classList.remove('nop'); };
    img.onerror = () => avanzar();
    img.src = src;
  };
  /* orden: portada de TMDB → otro póster de la película → imagen de fondo → recuadro con título */
  const avanzar = async () => {
    etapa++;
    if(etapa === 1){
      const p = await portadaAlterna(it);
      if(p && p !== it.poster){ poner(POSTER + p); return; }
      etapa++;
    }
    if(etapa === 2 && it.backdrop){ poner(IMG + 'w500' + it.backdrop); return; }
    const im = el.querySelector('img'); if(im) im.remove();
    el.classList.add('nop');
  };
  const ps = PORTADA_TEMPORADA[it.type + it.id], pl = PORTADA_IDIOMA[it.type + it.id];
  if(pl) portadaIdioma(it, pl).then(p => p ? poner(POSTER + p) : (it.poster ? poner(POSTER + it.poster) : avanzar()));
  else if(ps) portadaTemporada(it, ps).then(p => p ? poner(POSTER + p) : (it.poster ? poner(POSTER + it.poster) : avanzar()));
  else if(it.poster) poner(POSTER + it.poster); else avanzar();
  el.addEventListener('click', () => abrirDetalle(it));
  return el;
}

/* ========= FILAS ========= */
const FILAS = [
  {id:'nowplaying', t:'En cartelera', path:'/movie/now_playing', params:{region:REGION}, type:'movie', fallback:true},
  {id:'trending',   t:'Tendencias de la semana', path:'/trending/movie/week', params:{}, type:'movie'},
  {id:'upcoming',   t:'Próximamente', path:'/movie/upcoming', params:{region:REGION}, type:'movie', fallback:true},
  {id:'tv',         t:'Series populares', path:'/tv/popular', params:{}, type:'tv'},
  {id:'popular',    t:'Populares', path:'/movie/popular', params:{}, type:'movie'},
  {id:'toprated',   t:'Mejor valoradas', path:'/movie/top_rated', params:{}, type:'movie'},
  {id:'g28',        t:'Acción y aventura', path:'/discover/movie', params:{with_genres:'28,12',sort_by:'popularity.desc','vote_count.gte':200}, type:'movie'},
  {id:'g35',        t:'Comedia', path:'/discover/movie', params:{with_genres:'35',sort_by:'popularity.desc','vote_count.gte':200}, type:'movie'},
  {id:'g27',        t:'Terror y suspenso', path:'/discover/movie', params:{with_genres:'27,53',sort_by:'popularity.desc','vote_count.gte':200}, type:'movie'},
  {id:'g878',       t:'Ciencia ficción y fantasía', path:'/discover/movie', params:{with_genres:'878,14',sort_by:'popularity.desc','vote_count.gte':200}, type:'movie'},
  {id:'g16',        t:'Animación', path:'/discover/movie', params:{with_genres:'16',sort_by:'popularity.desc','vote_count.gte':200}, type:'movie'},
  {id:'g18',        t:'Drama', path:'/discover/movie', params:{with_genres:'18',sort_by:'popularity.desc','vote_count.gte':200}, type:'movie'},
  {id:'g10749',     t:'Romance', path:'/discover/movie', params:{with_genres:'10749',sort_by:'popularity.desc','vote_count.gte':200}, type:'movie'},
  {id:'g99',        t:'Documentales', path:'/discover/movie', params:{with_genres:'99',sort_by:'popularity.desc','vote_count.gte':100}, type:'movie'}
];

const rowsEl = document.getElementById('rows');
const obs = new IntersectionObserver(es => es.forEach(e => {
  if(e.isIntersecting){ obs.unobserve(e.target); cargarFila(e.target._fila, e.target); }
}), {rootMargin:'600px 0px'});

FILAS.forEach(f => {
  const row = document.createElement('section');
  row.className = 'row'; row.id = 'row-' + f.id; row._fila = f;
  row.innerHTML = `<h2>${esc(f.t)}</h2>
    <button class="arrow l" aria-label="Anterior"><svg viewBox="0 0 24 24"><path d="M15 5l-7 7 7 7"/></svg></button>
    <div class="strip">${'<div class="skel"></div>'.repeat(10)}</div>
    <button class="arrow r" aria-label="Siguiente"><svg viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></button>`;
  const strip = row.querySelector('.strip');
  row.querySelector('.l').onclick = () => strip.scrollBy({left:-strip.clientWidth*.85});
  row.querySelector('.r').onclick = () => strip.scrollBy({left: strip.clientWidth*.85});
  rowsEl.appendChild(row);
  obs.observe(row);
});

async function cargarFila(f, row){
  const strip = row.querySelector('.strip');
  try{
    let d = await tmdb(f.path, f.params);
    if(f.fallback && (d.results || []).filter(x => x.poster_path).length < 8){
      const p = {...f.params}; delete p.region;
      d = await tmdb(f.path, p);
    }
    const items = (d.results || []).filter(x => x.poster_path).map(x => norm(x, f.type));
    if(!items.length){ row.remove(); return; }
    strip.innerHTML = '';
    items.forEach(it => strip.appendChild(crearCard(it)));
  }catch(e){
    strip.innerHTML = `<div class="msg"><b>No se pudo cargar esta fila.</b> Revisa tu conexión a internet o la API key de TMDB.</div>`;
  }
}

/* ========= HERO ========= */
let heroItems = [], heroIdx = 0, heroTimer = null, bgActual = 'bgA';
const hc = document.getElementById('hc');

async function iniciarHero(){
  try{
    const d = await tmdb('/trending/movie/day');
    heroItems = (d.results || []).filter(x => x.backdrop_path && x.overview).slice(0,6).map(x => norm(x,'movie'));
    if(!heroItems.length) throw 0;
    const dots = document.getElementById('dots');
    heroItems.forEach((_, i) => {
      const s = document.createElement('span');
      s.onclick = () => { mostrarHero(i); reiniciarTimer(); };
      dots.appendChild(s);
    });
    mostrarHero(0);
    reiniciarTimer();
  }catch(e){
    document.getElementById('hTitle').textContent = 'GipaPlay';
    document.getElementById('hOver').textContent = 'No se pudo conectar con TMDB. Revisa tu conexión a internet o la API key.';
    ['hPlay','hInfo'].forEach(id => document.getElementById(id).style.display = 'none');
  }
}
function reiniciarTimer(){ clearInterval(heroTimer); heroTimer = setInterval(() => mostrarHero((heroIdx + 1) % heroItems.length), 9000); }
function mostrarHero(i){
  heroIdx = i;
  const it = heroItems[i];
  const pre = new Image();
  pre.onload = () => {
    if(heroIdx !== i) return;
    const nuevo = bgActual === 'bgA' ? 'bgB' : 'bgA';
    document.getElementById(nuevo).style.backgroundImage = `url(${BACK}${it.backdrop})`;
    document.getElementById(nuevo).classList.add('on');
    document.getElementById(bgActual).classList.remove('on');
    bgActual = nuevo;
  };
  pre.src = BACK + it.backdrop;
  hc.classList.add('fade');
  setTimeout(() => {
    document.getElementById('hTag').textContent = 'Tendencia hoy';
    document.getElementById('hTitle').textContent = it.title;
    document.getElementById('hMeta').innerHTML = `<span class="star">★ ${it.rating.toFixed(1)}</span>${it.year ? `<span>${it.year}</span>` : ''}<span>Película</span>`;
    document.getElementById('hOver').textContent = it.overview;
    hc.classList.remove('fade');
  }, 250);
  [...document.getElementById('dots').children].forEach((d, k) => d.classList.toggle('on', k === i));
}
['hPlay','hInfo'].forEach(id => document.getElementById(id).onclick = () => heroItems[heroIdx] && abrirDetalle(heroItems[heroIdx]));

/* ========= DETALLE + TRÁILER ========= */
const modal = document.getElementById('modal');
const box = document.getElementById('box');
let detalleActual = null;

function cerrarModal(){ limpiarPlayer(); modal.classList.remove('open'); box.innerHTML = ''; detalleActual = null; }
modal.addEventListener('click', e => { if(e.target === modal) cerrarModal(); });

function pintarModal(it, ex){
  it._ex = ex;
  const lista = enLista(it);
  const gen = ex && ex.genres ? ex.genres.map(g => `<span class="chip">${esc(g.name)}</span>`).join('') : '';
  const dur = ex && ex.runtime ? `<span class="chip">${Math.floor(ex.runtime/60)}h ${ex.runtime%60}min</span>` :
              (ex && ex.number_of_seasons ? `<span class="chip">${ex.number_of_seasons} temporada${ex.number_of_seasons>1?'s':''}</span>` : '');
