  const x = box.querySelector('#mClose'); if(x) x.style.display = 'none';
  box.insertAdjacentHTML('afterbegin', '<button class="back" id="mBack" aria-label="Volver" title="Volver"><svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 4 7 12 15 20"/></svg></button>');
  box.querySelector('#mBack').onclick = () => { const it = detalleActual; if(!it) return; limpiarPlayer(); pintarModal(it, it._ex); box.scrollTo({top:0}); };
}

