}
const sinAcentos = t => (t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
/* ===== Tráilers SOLO en español (latino primero), validados ===== */
const MALO = /\b(musica|music|soundtrack|ost|banda sonora|score|theme|lyrics?|letra|audio|clip|fan ?made|fan ?trailer|concept|reaccion|reaction|review|resena|analisis|explicacion|resumen|recap|escena|scene|behind|detras|making|entrevista|interview|subtitulad[oa]s?|subs?|subtitles?|vose|vos|sin voz|instrumental|remix|amv|edit|mashup|karaoke|cover|parodia|parody|gameplay|featurette|bloopers?|recopilacion|compilacion|compilation|momentos|moments|intro|opening|openings|ending|sigla|cancion|song|songs|mix|loop)\b/;
const ES_MARCA = /\b(latino|latam|latinoamerica|doblad[oa]|espanol|castellano|hispano|espana|mexico|argentina|peru|colombia|chile)\b/;
/* Solo español LATINO (sin "doblado"/"español" a secas, que puede ser de España) */
const LAT_MARCA = /\b(latino|latina|latam|latinoamerica|latinoamericano|hispanoamerica|mexico|argentina|peru|colombia|chile)\b/;
/* Señales de que el video está subtitulado en vez de doblado */
const SUBS_MARCA = /\b(subtitulad[oa]s?|subtitulos?|subtitles?|sub ?esp|sub ?espanol|sub|vose)\b/;
/* Canales de estudios y distribuidoras: sus tráilers se consideran oficiales */
const CANAL_OFICIAL = /(sony|marvel|disney|pixar|lucasfilm|netflix|warner|\bdc\b|universal|paramount|nickelodeon|cartoon network|prime video|amazon|\bhbo\b|\bmax\b|star\+|star plus|hulu|apple tv|lionsgate|20th century|\bfox\b|\ba24\b|dreamworks|illumination|\bmgm\b|studiocanal|diamond films|zima|cinepolis|crunchyroll|funimation|toei|bandai|focus features|\bneon\b|searchlight|legendary|blumhouse|pelimex|videocine|columbia|tristar|playstation|xbox|nintendo|ubisoft|lego)/;
/* Descripciones típicas de recopilaciones/fan edits con música */
const DESC_MALA = /\b(no copyright|copyright disclaimer|i do not own|i don t own|no me pertenece|no soy due[nñ]o|derechos de autor|fair use|uso justo|fan ?made|hecho por fans|music|musica|cancion|song|soundtrack|compilacion|compilation)\b/;
const LATAM = ['MX','AR','CL','CO','PE','VE','UY','EC','BO','PY','CR','PA','DO','GT','HN','SV','NI','CU','PR','419'];
/* true si el nombre del video delata que no es un tráiler normal (música, subtitulado, reacción, etc.) */
const nombreMalo = (nombre, titulos) => { let t = sinAcentos(nombre); [].concat(titulos).forEach(x => { if(x) t = t.replace(sinAcentos(x), ' '); }); return MALO.test(t); };
const PALABRAS_VACIAS = new Set(['the','of','and','vs','los','las','del','una','uno','con','por','para','contra','que','como','sin','sus']);
/* Palabras que pueden acompañar al título en un video sin cambiar de qué película es */
const GENERICAS = new Set(('trailer teaser oficial official doblado doblada latino latina latam latinoamerica latinoamericano espanol castellano espana hd 4k 1080p avance adelanto ' +
  'el la los las de del en y a un una the of and vs v contra con por para que al lo se su sus es pelicula film films movie serie full estreno cines cine ' +
  'marvel studios studio sony pictures disney pixar netflix warner bros universal paramount lionsgate century fox hbo max prime video amazon mgm apple tv dc lucasfilm ' +
  'nickelodeon cartoon network plus star a24 dreamworks illumination animation entertainment hispano mexico argentina peru colombia chile').split(' '));
/* ¿El texto habla de ESTA película y no de otra con nombre parecido? (Spider-Man 2 ≠ Spider-Man: Un nuevo día)
   Exige todas las palabras clave del título (números incluidos) y que no sobren palabras de otro subtítulo o secuela. */
function coincideTitulo(texto, titulos, it){
  const anio = +(it && it.year) || 0;
  const variantes = [s => sinAcentos(String(s).replace(/(\w)-(\w)/g, '$1$2')), sinAcentos];
  for(const norm of variantes){
    const tok = norm(texto).split(' ').filter(Boolean);
    for(const x of [].concat(titulos)){
      const n = norm(x).split(' ').filter(Boolean);
      const clave = n.filter(p => (p.length > 2 || /^\d+$/.test(p)) && !PALABRAS_VACIAS.has(p));
      if(!clave.length || !clave.every(p => tok.includes(p))) continue;
      let ok = true;
      for(const p of tok.filter(p => !n.includes(p) && !GENERICAS.has(p))){
        if(/^(19|20)\d\d$/.test(p)){ if(anio && Math.abs(+p - anio) > 1){ ok = false; break; } continue; }
        if(it && it.type === 'tv' && (/^\d+$/.test(p) || /^(temporada|season|t\d+)$/.test(p))) continue;
        ok = false; break;
      }
      if(ok) return true;
    }
  }
  return false;
}
const durSeg = iso => { const m = /^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/.exec(iso || ''); return m ? (+m[1]||0)*86400 + (+m[2]||0)*3600 + (+m[3]||0)*60 + (+m[4]||0) : 0; };

let ytMotivo = '';
async function anotarErr(r){
  let m = 'HTTP ' + r.status;
  try{ const d = await r.json(), e = d.error || {}; m = (e.errors && e.errors[0] && e.errors[0].reason) || e.message || m; }catch(_){}
  ytMotivo = m; console.warn('GipaPlay · YouTube API falló:', m);
}
/* Pide a YouTube los datos reales de los videos. null = no se pudo validar (sin clave / sin cuota). */
async function infoYT(keys){
  if(!keys.length) return new Map();
  if(!YT_API_KEY) return null;
  try{
    const u = new URL('https://www.googleapis.com/youtube/v3/videos');
    u.search = new URLSearchParams({part:'snippet,contentDetails,status,statistics', id:keys.slice(0,50).join(','), key:YT_API_KEY});
    const r = await fetch(u);
    if(!r.ok){ await anotarErr(r); return null; }
    const d = await r.json(), m = new Map();
    (d.items || []).forEach(v => m.set(v.id, v));
    return m;
  }catch(e){ ytMotivo = 'sin conexión con YouTube'; console.warn('GipaPlay · YouTube API:', e); return null; }
}
/* ¿Se puede ver de verdad y es un tráiler real? (existe, incrustable, no bloqueado en tu país, duración de tráiler, sin audio en otro idioma) */
function okYT(v, it){
  if(!v) return false;                                    /* borrado o privado */
  const st = v.status || {}, cd = v.contentDetails || {}, sn = v.snippet || {};
  if(st.embeddable === false || st.privacyStatus === 'private' || st.uploadStatus === 'rejected' || st.uploadStatus === 'deleted') return false;
  const rr = cd.regionRestriction;
  if(rr){ if(rr.blocked && rr.blocked.includes(REGION)) return false; if(rr.allowed && !rr.allowed.includes(REGION)) return false; }
  const s = durSeg(cd.duration);
  if(s < 30 || s > 420) return false;                     /* ni clips sueltos ni "música de 10 minutos" */
  if(+((v.statistics || {}).viewCount || 0) < 500) return false;   /* los falsos casi no tienen vistas */
  if(nombreMalo(sn.title, it._tits || it.title)) return false;
  if(/\b(amv|compilation|compilacion|fan ?made|fanmade|music|musica)\b/.test(sinAcentos((sn.tags || []).join(' ')))) return false;
  if(!CANAL_OFICIAL.test(sinAcentos(sn.channelTitle))){          /* canal desconocido: exige pruebas de que es un tráiler real */
    if(DESC_MALA.test(sinAcentos(sn.description))) return false;
    if(!/\b(oficial|official)\b/.test(sinAcentos(sn.title))) return false;
    if(+((v.statistics || {}).viewCount || 0) < 20000) return false;
  }
  const al = (sn.defaultAudioLanguage || '').toLowerCase(), dl = (sn.defaultLanguage || '').toLowerCase();
  const tc = sinAcentos(sn.title + ' ' + sn.channelTitle);
  if(/\b(espana|castellano)\b/.test(tc) || al === 'es-es') return false;        /* doblaje de España, no latino */
  if(SUBS_MARCA.test(sinAcentos(sn.title + ' ' + (sn.tags || []).join(' ')))) return false;
  if(/\b(subtitulado|subtitulada|vose)\b/.test(sinAcentos((sn.description || '').slice(0, 300)))) return false;
  /* PRUEBA de que es doblaje latino (no subtítulos): audio marcado en español, o el título/canal lo dicen */
  const marca = LAT_MARCA.test(tc) || /\bdoblad[oa]\b/.test(tc);
  if(al && !al.startsWith('es') && !marca) return false;   /* audio original (inglés, japonés…) sin marca de doblaje = subtitulado */
  if(!al.startsWith('es') && !marca) return false;         /* sin pruebas de que esté doblado */
  return true;
}
/* ===== Tráilers elegidos a mano (tienen prioridad sobre todo lo demás) =====
   Para agregar otro: {id: ID_DE_TMDB, type:'movie' o 'tv', titulo: /palabras del título/, key:'ID_DEL_VIDEO_DE_YOUTUBE'} */
const TRAILERS_MANUALES = [
  {id:429617, type:'movie', titulo:/lejos de casa|far from home/, key:'J4aOGV5hO6k'},   /* Spider-Man: Lejos de casa (latino) */
  {id:634649, type:'movie', titulo:/sin camino a casa|no way home/, key:'8nNa5A_MRBU'}, /* Spider-Man: Sin camino a casa (latino) */
  {id:475557, type:'movie', titulo:/^(joker|guason)( joker| guason)?$/, key:'TiKMDCmhhsY'},   /* Joker (2019) (latino) */
  {titulo:/scott pilgrim (da el salto|takes off)/, key:'LIgHiS4h7Jc'},   /* Scott Pilgrim da el salto (latino) */
  {titulo:/edgerunners\s*(2|ii)\b/, key:'-QiaX2Khdms'}   /* Cyberpunk: Edgerunners 2 */
];
function trailerManual(it, ex){
  const nombres = sinAcentos([it.title, ex && ex.original_title, ex && ex.original_name].filter(Boolean).join(' '));
  const m = TRAILERS_MANUALES.find(x => (!x.type || x.type === it.type) && (x.id === it.id || (x.titulo && x.titulo.test(nombres))));
  return m ? {key:m.key, label:'latino'} : null;
}
async function trailersES(it, vidsTMDB, ex){
  it._tits = [...new Set([it.title, ex && (ex.original_title || ex.original_name)].filter(Boolean))];
  const ck = 'gipaplay_tr9_' + it.type + it.id;
  try{ const c = localStorage.getItem(ck); if(c) return JSON.parse(c); }catch(e){}
  let fallo = false; ytMotivo = '';
  const cand = new Map();
  for(const v of vidsTMDB){
    if(v.site !== 'YouTube' || v.iso_639_1 !== 'es') continue;           /* solo videos marcados en español */
    if(v.type !== 'Trailer' && v.type !== 'Teaser') continue;             /* nada de clips, featurettes ni bloopers */
    if(nombreMalo(v.name, it._tits || it.title)) continue;
    const n = sinAcentos(v.name);
    const lat = LATAM.includes(v.iso_3166_1) || /latino|latam|hispano|mexico/.test(n);
    const esp = !lat && (v.iso_3166_1 === 'ES' || /espana|castellano/.test(n));
    if(esp || SUBS_MARCA.test(n)) continue;                                /* nada de España ni subtitulado; lo demás en español cuenta como latino */
    if(!cand.has(v.key)) cand.set(v.key, {key:v.key, teaser:v.type === 'Teaser', lat, esp, official:!!v.official});
  }
  let vmap = await infoYT([...cand.keys()]);
  if(YT_API_KEY && !vmap) fallo = true;
  const validos = () => [...cand.values()].filter(c => vmap ? okYT(vmap.get(c.key), it) : c.lat);   /* sin YouTube API: solo los marcados latino por TMDB */
  let lista = validos();

  /* Si TMDB no tiene uno latino que funcione, se busca en YouTube */
  const consultas = [...new Set([`${it.title} ${it.year || ''} tráiler oficial español latino`.replace(/\s+/g, ' '), ...it._tits.map(x => `${x} trailer latino`), `${it.title} tráiler latino`])];
  for(const qy of consultas){
    if(!YT_API_KEY || lista.some(c => c.lat)) break;
    try{
      const u = new URL('https://www.googleapis.com/youtube/v3/search');
      u.search = new URLSearchParams({part:'snippet', q:qy, type:'video', videoEmbeddable:'true', videoDuration:'short', maxResults:'15', relevanceLanguage:'es', regionCode:REGION, key:YT_API_KEY});
      const r = await fetch(u);
      if(!r.ok){ fallo = true; await anotarErr(r); }
      else{
        const d = await r.json();
        for(const i of (d.items || [])){
          const t = sinAcentos(i.snippet.title), ch = sinAcentos(i.snippet.channelTitle), tc = t + ' ' + ch;
          if(!coincideTitulo(i.snippet.title, it._tits, it) || !/\b(trailer|teaser|avance|adelanto)\b/.test(t)) continue;
          if(nombreMalo(i.snippet.title, it._tits || it.title) || !(LAT_MARCA.test(tc) || /\b(doblad[oa]|espanol)\b/.test(tc)) || /\b(espana|castellano)\b/.test(tc) || SUBS_MARCA.test(t)) continue;
          const lat = LAT_MARCA.test(tc), esp = false;
          if(!cand.has(i.id.videoId)) cand.set(i.id.videoId, {key:i.id.videoId, teaser:/teaser/.test(t), lat, esp, official:/oficial|official/.test(t)});
        }
        vmap = await infoYT([...cand.keys()]);
        if(!vmap) fallo = true;
        lista = validos();
      }
    }catch(e){ fallo = true; ytMotivo = 'sin conexión con YouTube'; console.warn('GipaPlay · YouTube API:', e); }
  }
  const vistas = c => +(((vmap && vmap.get(c.key) || {}).statistics || {}).viewCount || 0);
  const puntaje = c => (c.lat ? 0 : c.esp ? 100 : 50) + (c.teaser ? 3 : 0) - (c.official ? 1 : 0) - Math.log10(1 + vistas(c)) / 5;
  lista.sort((x, y) => puntaje(x) - puntaje(y));
  const res = lista.map(c => ({key:c.key, label:c.lat ? 'latino' : c.esp ? 'España' : 'español'}));
  console.log('GipaPlay · tráilers de "' + it.title + '":', res, ytMotivo ? '(YouTube: ' + ytMotivo + ')' : '');
  if(!fallo){ try{ localStorage.setItem(ck, JSON.stringify(res)); }catch(e){} }
  return res;
}
let ytPlayer = null, ytTimer = null, ytApiPromise = null, ytRO = null;
let vidLimpiar = null;
let EP_ACTUAL = null;   /* serie/episodio que se está reproduciendo (lo usa el reproductor para el "Siguiente episodio") */
function limpiarPlayer(){
  if(vidLimpiar){ const f = vidLimpiar; vidLimpiar = null; f(); }
  clearInterval(ytTimer); ytTimer = null;
  if(ytRO){ ytRO.disconnect(); ytRO = null; }
  try{ ytPlayer && ytPlayer.destroy(); }catch(e){}
  ytPlayer = null;
}
function cargarYT(){
  if(window.YT && YT.Player) return Promise.resolve();
  if(ytApiPromise) return ytApiPromise;
  ytApiPromise = new Promise((res, rej) => {
    const prev = window.onYouTubeIframeAPIReady;
    window.onYouTubeIframeAPIReady = () => { if(prev) prev(); res(); };
    const sc = document.createElement('script');
    sc.src = 'https://www.youtube.com/iframe_api';
    sc.onerror = () => { ytApiPromise = null; rej(); };
    document.head.appendChild(sc);
  });
  return ytApiPromise;
}
/* Tiempo del reproductor: m:ss y, desde la hora, h:mm:ss (2:18:28 en vez de 138:28) */
const fmtT = s => {
  s = Math.max(0, Math.floor(s || 0));
  const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), seg = String(s % 60).padStart(2, '0');
  return h ? h + ':' + String(m).padStart(2, '0') + ':' + seg : m + ':' + seg;
};
const IC = {
  play:'<svg viewBox="0 0 24 24"><path d="M6 4l14 8-14 8z"/></svg>',
  pause:'<svg viewBox="0 0 24 24"><path d="M6 4h4v16H6zM14 4h4v16h-4z"/></svg>',
  vol:'<svg viewBox="0 0 24 24"><path d="M3 9v6h4l5 4V5L7 9H3zm13.5 3a4.5 4.5 0 00-2.5-4v8a4.5 4.5 0 002.5-4z"/></svg>',
  mute:'<svg viewBox="0 0 24 24"><path d="M3 9v6h4l5 4V5L7 9H3zm13.6 3l2.4-2.4-1.4-1.4-2.4 2.4-2.4-2.4-1.4 1.4 2.4 2.4-2.4 2.4 1.4 1.4 2.4-2.4 2.4 2.4 1.4-1.4z"/></svg>',
  fs:'<svg viewBox="0 0 24 24"><path d="M4 4h6v2H6v4H4V4zm10 0h6v6h-2V6h-4V4zM4 14h2v4h4v2H4v-6zm10 0h4v-4h2v6h-6v-2z" style="display:none"/><path d="M4 4h6v2H6v4H4V4zm10 0h6v6h-2V6h-4V4zM4 14h2v4h4v2H4v-6zm14 0h2v6h-6v-2h4v-4z"/></svg>'
};
function avisoPlayer(html){
  const m = document.createElement('div');
  m.className = 'player';
  m.style.cssText = 'display:grid;place-items:center;text-align:center;padding:1.2rem;color:#b4c3d3;line-height:1.5;font-size:.95rem';
  m.innerHTML = '<div>' + html + '</div>';
  return m;
}
/* Clave donde se guarda el minuto en que se quedó cada película / episodio */
const claveVideo = (it, ep) => 'gipaplay_pos_' + it.type + it.id + (ep ? '_s' + ep.season + 'e' + ep.episode : '');
/* Progreso (0 a 100) de un episodio, para la barra de las tarjetas */
function progresoVideo(it, ep){
  try{
    const k = claveVideo(it, ep);
    const pos = +localStorage.getItem(k), dur = +localStorage.getItem(k + '_d');
    if(!pos || !dur) return 0;
    return Math.max(0, Math.min(100, pos / dur * 100));
  }catch(e){ return 0; }
}
/* Botón "Reproducir" de una serie: continúa el último episodio que viste (o el siguiente si ya lo terminaste);
   si no has visto nada, empieza por el primero disponible */
async function continuarSerie(it){
  await VIDEOS_LISTO;
  const lista = VIDEOS.filter(v => +v.tmdbId === it.id && v.temporada && urlOk(v.url))
    .sort((a, b) => (+a.temporada - +b.temporada) || (+a.episodio - +b.episodio));
  if(!lista.length) return reproducirPelicula(it);
  let idx = 0, ultimo = 0;
  try{
    lista.forEach((v, i) => {
      const t = +localStorage.getItem(claveVideo(it, {season:+v.temporada, episode:+v.episodio}) + '_t') || 0;
      if(t > ultimo){ ultimo = t; idx = i; }
    });
    if(ultimo){
      const k = claveVideo(it, {season:+lista[idx].temporada, episode:+lista[idx].episodio});
      const pos = +localStorage.getItem(k), dur = +localStorage.getItem(k + '_d');
      if(dur && pos >= dur - 31 && idx < lista.length - 1) idx++;
    }
  }catch(e){}
  const v = lista[idx];
  reproducirPelicula(it, {season:+v.temporada, episode:+v.episodio, name:v.titulo});
}
/* ===== Reproductor propio para archivos de video directos (.mp4, .webm, .m3u8…) =====
   Solo se ve el video con nuestra cinta de control; los subtítulos quedan siempre desactivados. */
const ES_VIDEO_DIRECTO = /\.(mp4|m4v|mov|webm|ogv|m3u8)(\?|#|$)|^https?:\/\/cdn\.savedly\.net\//i;
let hlsPromise = null;
function cargarHLS(){
  if(window.Hls) return Promise.resolve();
  if(hlsPromise) return hlsPromise;
  hlsPromise = new Promise((res, rej) => {
    const sc = document.createElement('script');
    sc.src = 'https://cdn.jsdelivr.net/npm/hls.js@1';
    sc.onload = res; sc.onerror = () => { hlsPromise = null; rej(); };
    document.head.appendChild(sc);
  });
  return hlsPromise;
}
function reproductorPropio(url, clave, respaldo){
  /* El video puede venir en varias partes (url = arreglo): se reproducen como una sola película,
     con una sola barra de tiempo y el salto entre partes preparado de antemano para que no se note. */
  const partes = (Array.isArray(url) ? url : [url]).filter(Boolean);
  const N = partes.length;
  const cp = document.createElement('div');
  cp.className = 'player cp paused';
  cp.innerHTML = `<video playsinline preload="auto"></video>
    <video class="off" playsinline preload="auto"></video>
    <div class="load show"><i></i></div>
    <div class="big"><b>${IC.play}</b></div>
    <div class="shield"></div>
    <div class="ctrl">
      <button id="cPlay" aria-label="Reproducir o pausar">${IC.play}</button>
      <span class="tm" id="cTime">0:00</span>
      <input type="range" id="cSeek" min="0" max="1000" value="0" aria-label="Progreso">
      <span class="tm" id="cDur">0:00</span>
      <button id="cMute" aria-label="Silenciar">${IC.vol}</button>
      <input type="range" id="cVol" min="0" max="100" value="100" aria-label="Volumen" style="--p:100%">
      <button id="cFs" aria-label="Pantalla completa">${IC.fs}</button>
    </div>
    <div class="nx" id="cNx" role="button" tabindex="0" aria-label="Ir al siguiente episodio">
      <div class="ring"><svg viewBox="0 0 36 36"><circle class="bg" cx="18" cy="18" r="16"/><circle class="fg" cx="18" cy="18" r="16"/></svg><span class="num" id="cNxN">10</span></div>
      <div class="tx"><small>Siguiente episodio</small><b id="cNxT"></b></div>
      <button class="x" id="cNxX" aria-label="Cancelar">✕</button>
    </div>`;
  const vids = cp.querySelectorAll('video'), $ = id => cp.querySelector('#' + id);
  let v = vids[0], reserva = vids[1];          /* v = el video que se ve; reserva = el que va cargando la parte siguiente */
  const seek = $('cSeek'), vol = $('cVol');
  let dragging = false, idleT = null, hls = null, bloqueado = false, muerto = false, terminado = false, sigInt = null;
  let idx = 0, pre = -1, cambiando = false, cambio = 0, vigT = null, sondeado = false, ultimo = 0;
  const setP = (el, x, max) => el.style.setProperty('--p', (max ? x / max * 100 : 0) + '%');
  vids[0]._i = 0;

  /* ---- duración de cada parte (la barra y el tiempo son los de la película completa) ---- */
  const dur = new Array(N).fill(0);
  const firma = partes.join('|');
  if(N > 1) try{
    const c = JSON.parse(localStorage.getItem(clave + '_pd'));
    if(c && c.u === firma && Array.isArray(c.d) && c.d.length === N && c.d.every(d => d > 0)) c.d.forEach((d, i) => { dur[i] = d; });
  }catch(e){}
  const off = i => { let s = 0; for(let k = 0; k < i; k++) s += dur[k]; return s; };
  const D = () => {
    const c = dur.filter(d => d > 0);
    if(!c.length) return 0;
    const s = c.reduce((a, b) => a + b, 0);
    return s + (N - c.length) * s / c.length;     /* mientras falten partes por medir, se estima */
  };
  const T = () => off(idx) + (v.currentTime || 0);
  const guardarDur = () => { if(N > 1 && dur.every(d => d > 0)) try{ localStorage.setItem(clave + '_pd', JSON.stringify({u: firma, d: dur})); }catch(e){} };
  const refrescarDur = () => { $('cDur').textContent = fmtT(D()); };
  /* duraciones que ya midió el bot: la barra muestra el total real desde el inicio y no se miden las partes una por una */
  if(N > 1){
    let alguna = false;
    partes.forEach((u, i) => { if(!(dur[i] > 0) && DURACIONES_API[u] > 0){ dur[i] = DURACIONES_API[u]; alguna = true; } });
    if(alguna) refrescarDur();
  }
  const medir = el => { if(el._i != null && isFinite(el.duration) && el.duration > 0){ dur[el._i] = el.duration; guardarDur(); refrescarDur(); } };
  const pintar = () => {
    const d = D(); if(!d) return;
    const t = T();
    $('cTime').textContent = fmtT(t);
    seek.value = t / d * 1000; setP(seek, +seek.value, 1000);
  };
  const sondas = {};
  const probar = i => {                            /* mide una parte sin reproducirla (solo sus metadatos) */
    if(dur[i] > 0) return Promise.resolve(dur[i]);
    if(sondas[i]) return sondas[i];
    return sondas[i] = new Promise(res => {
      const t = document.createElement('video');
      let fin = false;
      const cerrar = () => {
        if(fin) return; fin = true; clearTimeout(to);
        t.onloadedmetadata = t.onerror = null; t.removeAttribute('src'); try{ t.load(); }catch(e){}
        delete sondas[i]; res(dur[i] || 0);
      };
      const to = setTimeout(cerrar, 20000);
      t.preload = 'metadata'; t.muted = true;
      t.onloadedmetadata = () => { if(isFinite(t.duration) && t.duration > 0){ dur[i] = t.duration; guardarDur(); refrescarDur(); } cerrar(); };
      t.onerror = cerrar;
      t.src = partes[i];
