      const d = dur[i] > 0 ? dur[i] : await probar(i);
      if(!d) return {i, local: Math.max(0, t - acc)};
      if(t < acc + d || i === N - 1) return {i, local: Math.min(Math.max(0, t - acc), d)};
      acc += d;
    }
  };
  vids.forEach(el => {
    el.addEventListener('loadedmetadata', () => medir(el));
    el.addEventListener('durationchange', () => medir(el));
  });

  /* subtítulos: siempre desactivados */
  vids.forEach(el => {
    const sinSubs = () => { for(const t of el.textTracks) t.mode = 'disabled'; };
    el.textTracks.addEventListener('addtrack', sinSubs);
    el.addEventListener('loadedmetadata', sinSubs);
  });

  /* continuar donde se quedó: el minuto (de la película completa) se guarda en el navegador */
  const posInicial = () => {
    let t0 = 0, dTot = 0;
    try{ t0 = +localStorage.getItem(clave) || 0; dTot = +localStorage.getItem(clave + '_d') || 0; }catch(e){}
    return t0 > 5 && (!dTot || t0 < dTot - 30) ? t0 : 0;
  };
  const guardar = () => {
    if(muerto || cambiando || !v.getAttribute('src')) return;   /* al cerrar, el video ya está vacío (tiempo 0): no se guarda */
    try{
      const d = D(); if(!d) return;
      const cur = v.currentTime || 0;
      const t = T();
      /* al terminar queda guardado como "visto completo" (barra llena); la próxima vez empieza de cero */
      const fin = terminado || (idx === N - 1 && v.ended) || t > d - 30;
      if(!fin && t <= 5 && idx === 0) return;
      /* la posición exacta se guarda también como (parte, segundo dentro de esa parte): no depende de medir las demás */
      if(N > 1){
        if(fin) localStorage.removeItem(clave + '_p');
        else localStorage.setItem(clave + '_p', JSON.stringify({u: firma, i: idx, l: Math.floor(cur)}));
      }
      /* el total (para la barra de las tarjetas) solo se guarda si ya se midieron las partes anteriores */
      let ok = true; for(let k = 0; k < idx; k++) if(!(dur[k] > 0)) ok = false;
      if(!ok) return;
      localStorage.setItem(clave, String(Math.floor(fin ? d : t)));
      localStorage.setItem(clave + '_d', String(Math.floor(d)));
