  const wake = () => {
    cp.classList.remove('idle'); clearTimeout(idleT);
    if(!v.paused) idleT = setTimeout(() => cp.classList.add('idle'), 2500);
  };
  cp.addEventListener('mousemove', wake);
  cp.addEventListener('touchstart', wake, {passive:true});

  const toggle = () => {
    if(v.paused || v.ended){ iniciar(); return; }
    /* mientras carga no se pausa (un clic durante la espera dejaba el video detenido) */
    if(v.readyState < 3) return;
    v.pause();
  };
