  cp.querySelector('.shield').onclick = toggle;
  cp.querySelector('.shield').ondblclick = fullscreen;
  $('cPlay').onclick = toggle;
  $('cFs').onclick = fullscreen;
  $('cMute').onclick = () => { v.muted = !v.muted; };
  centroMovil(cp, {toggle, wake, reproduciendo: () => !v.paused && !v.ended, saltar: d => saltar(T() + d)});
  /* Volumen por encima de 100 % (hasta 200 %): se amplifica con Web Audio. Solo se activa si el servidor del video
