    cargando.classList.toggle('show', espera || cambiando || (v.paused && v.readyState < 2 && !!v.getAttribute('src') && !bloqueado));
    grande.classList.toggle('show', !cambiando && v.paused && !espera && (bloqueado || v.readyState >= 2) && !v.ended && T() < 1);
  };
  const fallo = i => {
    limpiarPlayer();
    const a = avisoPlayer('No se pudo cargar el video' + (N > 1 ? ' (parte ' + (i + 1) + ' de ' + N + ')' : '') + '.<br>Revisa tu conexión e inténtalo de nuevo.');
    a.id = 'mTop';
    cp.replaceWith(a);
  };
  vids.forEach(el => {
    const on = (ev, fn) => el.addEventListener(ev, e => { if(el === v) fn(e); });   /* solo cuenta el video que se está viendo */
    ['loadstart','waiting','stalled','canplay','canplaythrough','playing','pause','seeked','loadeddata'].forEach(ev => on(ev, ver));
    on('playing', () => { if(!sondeado){ sondeado = true; (async () => { for(let i = 0; i < N && !muerto; i++) await probar(i); })(); } });
    on('play', () => { cp.classList.remove('paused'); $('cPlay').innerHTML = IC.pause; wake(); });
    on('pause', () => { guardar(); cp.classList.add('paused'); cp.classList.remove('idle'); $('cPlay').innerHTML = IC.play; });
    on('ended', () => {
      if(idx < N - 1){ if(!cambiando) ir(idx + 1, 0, true); return; }   /* respaldo: la parte terminó sin que el salto anticipado ocurriera */
