      v = el; idx = i; reserva = viejo; pre = -1;
      el.classList.remove('off'); viejo.classList.add('off');
      if(reproducir) iniciar();
      viejo.pause(); viejo.removeAttribute('src'); try{ viejo.load(); }catch(e){}
      refrescarDur();
    }else{
      idx = i; el._i = i;                      /* al retomar en una parte adelantada, idx debe ser esa parte (antes se quedaba en 0) */
      if(reproducir) iniciar();
      refrescarDur();
