     Aparece cuando empiezan los créditos: el momento sale del campo "creditos" del episodio en la API
     (segundos, o "mm:ss"), o del campo "outro" del episodio, o del valor de toda la serie en outros.json
     (cuántos segundos dura el final, contados desde el fin del episodio). Si no hay ninguno, unos 90 s antes del final. */
  const ctxEp = EP_ACTUAL;
  if(ctxEp && ctxEp.ep){
    const eps = VIDEOS.filter(x => +x.tmdbId === ctxEp.it.id && x.temporada && urlOk(x.url))
      .sort((a, b) => (+a.temporada - +b.temporada) || (+a.episodio - +b.episodio));
    const k = eps.findIndex(x => +x.temporada === ctxEp.ep.season && +x.episodio === ctxEp.ep.episode);
    const sig = k >= 0 ? eps[k + 1] : null;
    if(sig){
      const aSeg = x => {
        if(typeof x === 'number') return isFinite(x) && x >= 0 ? x : null;
        if(typeof x === 'string' && /^\d+(:\d{1,2}){0,2}$/.test(x.trim())){
          const n = x.trim().split(':').reduce((a, b) => a * 60 + (+b), 0);
          return isFinite(n) ? n : null;
        }
        return null;
      };
      const tCred = aSeg(eps[k].creditos);
      let tOutro = tCred == null ? aSeg(eps[k].outro) : null;
      if(tCred == null && tOutro == null){                 /* outros.json: valor de la serie, o uno por episodio ("1x3") con "*" como general */
        const cfg = OUTROS_API[ctxEp.it.id];
        if(cfg && typeof cfg === 'object' && !Array.isArray(cfg)){
          tOutro = aSeg(cfg[ctxEp.ep.season + 'x' + ctxEp.ep.episode]);
          if(tOutro == null) tOutro = aSeg(cfg['*']);
        }else tOutro = aSeg(cfg);
      }
      /* un valor de más de 10 min no puede ser lo que dura el outro: se toma como el minuto donde empieza */
      let tInicio = tCred;
      if(tInicio == null && tOutro != null && tOutro > 600){ tInicio = tOutro; tOutro = null; }
      const nx = $('cNx'), num = $('cNxN'), fg = nx.querySelector('.fg');
      const CUENTA = 10, LARGO = 100.53;
      let restante = CUENTA, visible = false, cancelado = false, yaVa = false, ult = 0;
      $('cNxT').textContent = 'T' + sig.temporada + ' · E' + sig.episodio + (sig.titulo ? ' · ' + sig.titulo : '');
      const pintarCuenta = () => {
        num.textContent = Math.max(0, Math.ceil(restante));
        fg.style.strokeDashoffset = String(LARGO * (1 - Math.max(0, restante) / CUENTA));
      };
      const ocultarSig = () => { visible = false; nx.classList.remove('show'); restante = CUENTA; pintarCuenta(); };
      const irSiguiente = () => {
        if(yaVa || muerto) return;
        yaVa = true; terminado = true;       /* el episodio queda como visto */
        reproducirPelicula(ctxEp.it, {season:+sig.temporada, episode:+sig.episodio, name:sig.titulo});
      };
      nx.onclick = irSiguiente;
      nx.onkeydown = e => { if(e.key === 'Enter'){ e.preventDefault(); e.stopPropagation(); irSiguiente(); } };
      nx.addEventListener('dblclick', e => e.stopPropagation());
      $('cNxX').onclick = e => { e.stopPropagation(); cancelado = true; ocultarSig(); };
      pintarCuenta();
      sigInt = setInterval(() => {
        if(muerto || yaVa) return;
        const ahora = performance.now(), dt = Math.min(0.5, (ahora - ult) / 1000); ult = ahora;
        if(cambiando) return;
        const d = D(); if(!d) return;
        const t = T();
        const fin = idx === N - 1 && v.ended;
        const desde = tInicio != null ? Math.min(tInicio, Math.max(0, d - 3))
          : Math.max(0, d - (tOutro != null ? Math.max(3, tOutro) : Math.min(90, d * 0.12)));
        if(!visible){
          if(!cancelado && (t >= desde || fin)){ visible = true; restante = CUENTA; pintarCuenta(); nx.classList.add('show'); }
          return;
        }
        /* si se retrocede antes del momento indicado, el cuadro se esconde y vuelve a salir cuando toque */
        if(!fin && t < desde - 1){ cancelado = false; ocultarSig(); return; }
        if(!v.paused || fin){
          restante -= dt; pintarCuenta();
          if(restante <= 0) irSiguiente();
        }
      }, 100);
    }
  }

  const teclas = e => {
    if(!cp.isConnected){ document.removeEventListener('keydown', teclas); return; }
    /* Las barras (progreso/volumen) ya no mueven el video con sus propios pasos diminutos:
       las flechas siempre saltan 10 s, aunque la barra tenga el foco */
    const enBarra = e.target.type === 'range' && cp.contains(e.target);
    if((e.target.tagName === 'INPUT' && !enBarra) || e.target.tagName === 'SELECT') return;
    if(e.key === ' '){ e.preventDefault(); toggle(); wake(); }
    else if(e.key === 'ArrowRight'){ e.preventDefault(); saltar(T() + 10); wake(); }
    else if(e.key === 'ArrowLeft'){ e.preventDefault(); saltar(T() - 10); wake(); }
    else if(e.key === 'f' || e.key === 'F') fullscreen();
    else if(e.key === 'm' || e.key === 'M') v.muted = !v.muted;
  };
  document.addEventListener('keydown', teclas);
  vidLimpiar = () => {
    guardar();
    muerto = true; clearInterval(vigT); clearInterval(sigInt);
    removeEventListener('pagehide', guardar);
    document.removeEventListener('keydown', teclas);
    clearTimeout(idleT);
    try{ hls && hls.destroy(); }catch(e){}
    vids.forEach(el => { el.pause(); el.removeAttribute('src'); try{ el.load(); }catch(e){} });
    try{ ctxA && ctxA.close(); }catch(e){}
  };

  const arrancar = async () => {
    await habilitarBoost();
    if(muerto) return;
    const t0 = posInicial();
    if(t0 && N > 1){
      cambiando = true; ver();
      let loc = null;
      try{
        const p = JSON.parse(localStorage.getItem(clave + '_p'));
        if(p && p.u === firma && Number.isInteger(p.i) && p.i >= 0 && p.i < N && isFinite(p.l) && p.l >= 0) loc = {i: p.i, local: p.l};
      }catch(e){}
      if(!loc) loc = await localizar(t0);
      if(muerto) return;
      poner(v, loc.i);
      await colocar(v, loc.i, loc.local, true);
    }else{
      poner(v, 0);
      await colocar(v, 0, t0, true);
    }
  };
  if(N === 1 && /\.m3u8(\?|#|$)/i.test(partes[0]) && !v.canPlayType('application/vnd.apple.mpegurl')){
    const t0 = posInicial();
    v.addEventListener('loadedmetadata', () => { if(t0) v.currentTime = t0; }, {once:true});
    cargarHLS().then(() => {
      if(!cp.isConnected && !v.isConnected) return;
      if(window.Hls && Hls.isSupported()){
        hls = new Hls();
        hls.subtitleDisplay = false;
        hls.on(Hls.Events.MANIFEST_PARSED, () => { hls.subtitleTrack = -1; iniciar(); });
        hls.loadSource(partes[0]); hls.attachMedia(v);
      }else cp.replaceWith(avisoPlayer('Tu navegador no puede reproducir este formato.'));
    }).catch(() => cp.replaceWith(avisoPlayer('No se pudo cargar el reproductor de video.')));
  }else arrancar();
  return cp;
}

/* ===== Savedly dentro de nuestro reproductor =====
   Se lee la página /embed/ de Savedly para sacar el enlace directo del video y reproducirlo con nuestro reproductor
   (con autoplay y minuto guardado). Si el navegador bloquea la lectura (CORS) se prueba con un proxy público y,
   si tampoco se consigue, se muestra el embed de Savedly tal cual. */
const SAVEDLY_RE = /^https?:\/\/(?:www\.)?savedly\.net\/(?:f|embed)\/([\w-]+)/i;
const savedlyCache = {};
/* Busca el enlace directo del video dentro del HTML (o JS empaquetado) de la página /embed/ de Savedly */
function extraerVideoSavedly(html){
  html = html.replace(/\\\//g, '/').replace(/&amp;/g, '&').replace(/\\u0026/g, '&');
  /* JS empaquetado (eval(function(p,a,c,k,e,d)…)) */
  const pk = /\}\('((?:[^'\\]|\\.)*)',(\d+),(\d+),'((?:[^'\\]|\\.)*)'\.split\('\|'\)/.exec(html);
  if(pk){
    try{
      const w = pk[4].split('|'), base = +pk[2];
      const cod = n => (n < base ? '' : cod(Math.floor(n / base))) + ((n %= base) > 35 ? String.fromCharCode(n + 29) : n.toString(36));
      const dic = {}; let c = +pk[3];
      while(c--) dic[cod(c)] = w[c] || cod(c);
      html += '\n' + pk[1].replace(/\\'/g, "'").replace(/\b\w+\b/g, x => dic[x] || x).replace(/\\\//g, '/');
    }catch(e){}
  }
  /* cadenas en base64 que contengan una URL de video */
  for(const b of html.match(/[A-Za-z0-9+\/=]{40,}/g) || []){
    try{ const d = atob(b); if(/^https?:\/\/\S+\.(mp4|m3u8|webm)/i.test(d)) html += '\n' + d; }catch(e){}
  }
  const pats = [
    /<(?:video|source)[^>]+src=["']([^"']+)["']/i,
    /["']?(?:file|src|source|url|video_url|videoUrl)["']?\s*[:=]\s*["'](https?:\/\/[^"']+)["']/i,
    /https?:\/\/[^"'\s<>\\]+?\.(?:m3u8|mp4|webm)(?:\?[^"'\s<>\\]*)?/i,
    /https?:\/\/cdn\.savedly\.net\/[^"'\s<>\\]+/i
  ];
  for(const re of pats){
    const m = re.exec(html);
    if(m){
      const u = (m[1] || m[0]).trim();
      if(/^https?:\/\//i.test(u) && !/\.(js|css|png|jpe?g|gif|svg|ico|vtt|srt)(\?|$)/i.test(u)) return u;
    }
  }
  return null;
}
async function resolverSavedly(id){
  if(savedlyCache[id]) return savedlyCache[id];
  try{ const g = localStorage.getItem('savedly_' + id); if(g){ savedlyCache[id] = g; return g; } }catch(e){}
  const paginas = ['https://savedly.net/embed/' + id, 'https://savedly.net/f/' + id];
  const proxys = [
    u => u,
    u => 'https://api.allorigins.win/raw?url=' + encodeURIComponent(u),
    u => 'https://api.codetabs.com/v1/proxy/?quest=' + encodeURIComponent(u),
    u => 'https://corsproxy.io/?' + encodeURIComponent(u),
    u => 'https://thingproxy.freeboard.io/fetch/' + u
  ];
  /* todos los intentos corren a la vez; gana el primero que devuelva un video */
  const pruebas = [];
  for(const pg of paginas) for(const px of proxys) pruebas.push((async () => {
    const ctl = new AbortController(), t = setTimeout(() => ctl.abort(), 10000);
    try{
      const r = await fetch(px(pg), {signal:ctl.signal});
      if(!r.ok) throw 0;
      const u = extraerVideoSavedly(await r.text());
      if(!u) throw 0;
      return u;
    }finally{ clearTimeout(t); }
  })());
  try{
    const u = await Promise.any(pruebas);
    savedlyCache[id] = u;
    try{ localStorage.setItem('savedly_' + id, u); }catch(e){}
    return u;
  }catch(e){ return null; }
}
async function reproducirPelicula(it, ep){
  await VIDEOS_LISTO;
  if(detalleActual !== it) return;
  let cur = document.getElementById('mTop') || box.querySelector('.player');
  if(!cur) return;
  limpiarPlayer();
  EP_ACTUAL = ep ? {it, ep} : null;
  /* En pantalla completa (p. ej. al pasar solo al siguiente episodio) el contenedor se conserva, para no salir de ella */
  const fsAct = document.fullscreenElement || document.webkitFullscreenElement;
  if(cur.classList.contains('cp') && (fsAct === cur || cur.classList.contains('pfs'))){
    const hijo = document.createElement('div');
    hijo.className = 'player'; hijo.id = 'mTop';
    const guardadas = [...cur.classList].filter(c => c === 'pfs' || c === 'rot');
    cur.removeAttribute('id'); cur.className = ['cp', 'fsw', ...guardadas].join(' '); cur.replaceChildren(hijo);
    cur = hijo;
  }
  let url = typeof FUENTE_PELICULA === 'function' ? FUENTE_PELICULA(it, ep) : null;
  /* Varias partes: nuestro reproductor las une como una sola película */
  if(Array.isArray(url)){
    const pm = reproductorPropio(url, claveVideo(it, ep));
    pm.id = 'mTop';
    cur.replaceWith(pm);
    ponerVolver();
    return;
  }
  /* Savedly: la página /f/ y la /embed/ son distintas; siempre se usa el embed (solo el reproductor) */
  if(url) url = url.replace(/^(https?:\/\/(?:www\.)?savedly\.net)\/f\/([\w-]+)/i, '$1/embed/$2');
  /* Savedly: se intenta sacar el video directo para usar nuestro reproductor (autoplay incluido) */
  const svm = url && SAVEDLY_RE.exec(url);
  if(svm){
    const esp = avisoPlayer('Cargando video…');
    esp.id = 'mTop';
    cur.replaceWith(esp);
    ponerVolver();
    const directo = await resolverSavedly(svm[1]);
    if(detalleActual !== it || !esp.isConnected) return;
    let ps;
    if(directo) ps = reproductorPropio(directo, claveVideo(it, ep), 'https://savedly.net/embed/' + svm[1] + '?autoplay=1&autostart=1');
    else{
      ps = document.createElement('div');
      ps.className = 'player';
      ps.innerHTML = '<iframe allowfullscreen allow="autoplay; fullscreen; encrypted-media; picture-in-picture"></iframe>';
      ps.firstChild.src = 'https://savedly.net/embed/' + svm[1] + '?autoplay=1&autostart=1&muted=0';
    }
    ps.id = 'mTop';
    esp.replaceWith(ps);
    return;
  }
  /* Enlaces de YouTube: se reproducen con el reproductor propio (mismo que los tráilers) */
  const ytm = url && /(?:youtube\.com\/(?:embed\/|watch\?(?:.*&)?v=)|youtu\.be\/)([\w-]{11})/.exec(url);
  if(ytm){
    cur.id = 'mTop';
    reproducirTrailer(ytm[1], claveVideo(it, ep));
    return;
  }
  let p;
  if(!url) p = avisoPlayer('<b style="color:#fff">' + esc(it.title) + (ep ? ' · T' + ep.season + ':E' + ep.episode : '') + '</b><br>Este título todavía no está disponible para reproducir.');
  else if(ES_VIDEO_DIRECTO.test(url)) p = reproductorPropio(url, claveVideo(it, ep));
  else{
    /* Página externa (no es un archivo de video): se muestra tal cual en un iframe */
    p = document.createElement('div');
    p.className = 'player';
    p.innerHTML = '<iframe allowfullscreen allow="autoplay; fullscreen; encrypted-media; picture-in-picture"></iframe>';
    p.firstChild.src = url;
  }
  p.id = 'mTop';
  cur.replaceWith(p);
  ponerVolver();
}
async function reproducirTrailer(key, clave){
  const yt = 'https://www.youtube.com/watch?v=' + encodeURIComponent(key);
  const top = document.getElementById('mTop');
  if(!top) return;
  const it = detalleActual;
  /* YouTube bloquea (error 153) los videos incrustados en archivos abiertos con file://.
     Hay que abrir la página desde un servidor (localhost / Vercel). */
  if(location.protocol === 'file:'){
    ponerVolver();
    top.replaceWith(avisoPlayer('Para ver el tráiler <b style="color:#fff">dentro de la página</b>, ábrela con <b style="color:#fff">iniciar.bat</b> (servidor local) o súbela a Vercel.<br><br><a href="' + yt + '" target="_blank" rel="noopener" style="color:#e23a3a">Mientras tanto, ver en YouTube</a>'));
    return;
  }
  limpiarPlayer();
  const cp = document.createElement('div');
  cp.className = 'player cp paused';
  cp.innerHTML = `<div id="ytHost"></div>
    <div class="shield"></div>
    <div class="cover" style="${it && it.backdrop ? `background-image:url(${IMG}w780${it.backdrop})` : ''}"><button class="btn play" id="cReplay">↻ Volver a ver</button></div>
    <div class="ctrl">
      <button id="cPlay" aria-label="Reproducir o pausar">${IC.play}</button>
      <span class="tm" id="cTime">0:00</span>
      <input type="range" id="cSeek" min="0" max="1000" value="0" aria-label="Progreso">
      <span class="tm" id="cDur">0:00</span>
      <button id="cMute" aria-label="Silenciar">${IC.vol}</button>
      <input type="range" id="cVol" min="0" max="100" value="100" aria-label="Volumen" style="--p:100%">
      <button id="cFs" aria-label="Pantalla completa">${IC.fs}</button>
    </div>`;
  top.replaceWith(cp);
  ponerVolver();

  try{ await cargarYT(); }
  catch(e){ cp.replaceWith(avisoPlayer('No se pudo cargar el reproductor.<br><br><a href="' + yt + '" target="_blank" rel="noopener" style="color:#e23a3a">Ver en YouTube</a>')); return; }
  if(!cp.isConnected) return;

  const $ = id => cp.querySelector('#' + id);
  const cover = cp.querySelector('.cover');
  const seek = $('cSeek'), vol = $('cVol');
  let dragging = false, idleT = null;
  const setP = (el, v, max) => el.style.setProperty('--p', (max ? v / max * 100 : 0) + '%');
  const estado = () => { try{ return ytPlayer.getPlayerState(); }catch(e){ return -1; } };
  const wake = () => {
    cp.classList.remove('idle'); clearTimeout(idleT);
    if(estado() === 1) idleT = setTimeout(() => cp.classList.add('idle'), 2500);
  };
  cp.addEventListener('mousemove', wake);
  cp.addEventListener('touchstart', wake, {passive:true});

  /* Solo cuando es una película (clave): se guarda el minuto y se retoma al volver. Los tráilers no pasan clave. */
  let ultimoG = 0;
  const guardar = () => {
    try{
      if(!clave || !ytPlayer || !ytPlayer.getDuration) return;
      const d = ytPlayer.getDuration(), c = ytPlayer.getCurrentTime();
      if(!d) return;
      const fin = estado() === 0 || c > d - 30;
      if(!fin && c <= 5) return;
      localStorage.setItem(clave, String(Math.floor(fin ? d : c)));
      localStorage.setItem(clave + '_d', String(Math.floor(d)));
      localStorage.setItem(clave + '_t', String(Date.now()));
    }catch(e){}
  };
  if(clave){
    addEventListener('pagehide', guardar);
    vidLimpiar = () => { guardar(); removeEventListener('pagehide', guardar); };
  }
  const toggle = () => { estado() === 1 ? ytPlayer.pauseVideo() : ytPlayer.playVideo(); };
  const fullscreen = () => pantallaCompletaHorizontal(cp);
  cp.querySelector('.shield').onclick = toggle;
  cp.querySelector('.shield').ondblclick = fullscreen;
  $('cPlay').onclick = toggle;
  $('cFs').onclick = fullscreen;
  centroMovil(cp, {toggle, wake, reproduciendo: () => estado() === 1, saltar: d => { try{ ytPlayer.seekTo(Math.max(0, ytPlayer.getCurrentTime() + d), true); }catch(e){} }});
  $('cReplay').onclick = () => { cover.classList.remove('show'); ytPlayer.seekTo(0, true); ytPlayer.playVideo(); };
  $('cMute').onclick = () => {
    if(ytPlayer.isMuted()){ ytPlayer.unMute(); $('cMute').innerHTML = IC.vol; }
    else { ytPlayer.mute(); $('cMute').innerHTML = IC.mute; }
  };
  vol.oninput = () => {
    const v = +vol.value; setP(vol, v, 100);
    ytPlayer.setVolume(v);
    if(v > 0 && ytPlayer.isMuted()){ ytPlayer.unMute(); }
    $('cMute').innerHTML = v === 0 ? IC.mute : IC.vol;
  };
  seek.oninput = () => { dragging = true; setP(seek, +seek.value, 1000); $('cTime').textContent = fmtT(ytPlayer.getDuration() * seek.value / 1000); };
  seek.onchange = () => { ytPlayer.seekTo(ytPlayer.getDuration() * seek.value / 1000, true); dragging = false; };

  const tick = () => {
    if(!ytPlayer || !ytPlayer.getDuration) return;
    const d = ytPlayer.getDuration(), c = ytPlayer.getCurrentTime();
    $('cDur').textContent = fmtT(d);
    if(dragging) return;
    if(clave && estado() === 1 && Math.abs(c - ultimoG) >= 5){ ultimoG = c; guardar(); }
    $('cTime').textContent = fmtT(c);
    seek.value = d ? c / d * 1000 : 0;
    setP(seek, +seek.value, 1000);
  };

  /* El video (16:9) se centra y el iframe se extiende por arriba y por abajo: el título, la cuenta,
     "Más videos", el logo de YouTube y las sombras que YouTube pone al pausar quedan fuera del área visible
     y se recortan, sin tapar el video con ninguna sombra propia. */
  const acomodar = () => {
    let f; try{ f = ytPlayer.getIframe(); }catch(e){ return; }
    if(!f) return;
    const cw = cp.clientWidth, ch = cp.clientHeight;
    if(!cw || !ch) return;
    const vw = Math.min(cw, ch * 16 / 9), vh = vw * 9 / 16;
    const pad = Math.max(170, vh * 0.35);
    f.style.cssText = `position:absolute;border:0;width:${vw}px;height:${vh + 2*pad}px;left:${(cw - vw)/2}px;top:${(ch - vh)/2 - pad}px`;
  };
  ytRO = new ResizeObserver(acomodar);
  ytRO.observe(cp);

  let reanudar = 0;
  if(clave){
    try{
      const pos = +localStorage.getItem(clave) || 0, dur = +localStorage.getItem(clave + '_d') || 0;
      if(pos > 5 && !(dur && pos >= dur - 31)) reanudar = Math.floor(pos);   /* si la vio completa, empieza de cero */
    }catch(e){}
  }
  ytPlayer = new YT.Player('ytHost', {
    videoId: key,
    playerVars: {autoplay:1, ...(reanudar ? {start:reanudar} : {}), controls:0, disablekb:1, fs:0, modestbranding:1, rel:0, iv_load_policy:3, playsinline:1, hl:'es', cc_lang_pref:'es', cc_load_policy:0, vq:'hd1080', origin:location.origin},
    events: {
      onReady: e => { acomodar(); e.target.playVideo(); ytTimer = setInterval(tick, 250); },
      onStateChange: e => {
        const st = e.data;
        if(st === 1){ try{ if(ytPlayer.getPlaybackQuality() !== 'hd1080') ytPlayer.setPlaybackQuality('hd1080'); }catch(_){}   /* pide 1080p (60 fps si el video lo tiene) */
          cp.classList.remove('paused'); cover.classList.remove('show'); $('cPlay').innerHTML = IC.pause; wake(); }
        else if(st === 2 || st === 5 || st === -1){ if(st === 2) guardar(); cp.classList.add('paused'); $('cPlay').innerHTML = IC.play; cp.classList.remove('idle'); }
        else if(st === 0){ guardar(); cp.classList.add('paused'); $('cPlay').innerHTML = IC.play; cp.classList.remove('idle'); cover.classList.add('show'); }
      },
      onError: ev => {
        const cod = ev && ev.data, lista = clave ? [] : ((it && it._trs) || []), sig = lista[lista.findIndex(t => t.key === key) + 1];
        limpiarPlayer();
        if(sig){ cp.id = 'mTop'; reproducirTrailer(sig.key); return; }
        const motivo = {2:'enlace de video inválido', 5:'error del reproductor HTML5', 100:'el video fue eliminado o es privado', 101:'el dueño del video no permite verlo fuera de YouTube (o está restringido en tu país)', 150:'el dueño del video no permite verlo fuera de YouTube (o está restringido en tu país)', 152:'el video tiene restricción de edad o de región', 153:'el navegador no envió el origen de la página (revisa la privacidad/extensiones)'}[cod] || 'error desconocido';
        console.warn('GipaPlay · YouTube error', cod, key);
        cp.replaceWith(avisoPlayer((clave ? 'Esta película no se puede reproducir aquí.' : 'Este tráiler no se puede reproducir aquí.') + '<br><span style="font-size:.8rem;opacity:.6">Código ' + cod + ': ' + motivo + '</span><br><br><a href="' + yt + '" target="_blank" rel="noopener" style="color:#e23a3a">Ver en YouTube</a>'));
      }
    }
  });
}
async function abrirDetalle(it){
  detalleActual = it;
  pintarModal(it, null);
  modal.classList.add('open');
  try{
    /* Se piden los videos por separado en español (México), español general e inglés,
       porque TMDB solo devuelve en cada consulta los videos del idioma pedido. */
    const vacio = () => ({results:[]});
    const base = `/${it.type}/${it.id}`;
    const [ex, vMX, vES] = await Promise.all([
      tmdb(base, {append_to_response:'credits'}),
      tmdb(base + '/videos', {language:'es-MX'}).catch(vacio),
      tmdb(base + '/videos', {language:'es'}).catch(vacio)
    ]);
    if(detalleActual !== it) return;
    const vistos = new Set();
    const vids = [...vMX.results, ...vES.results].filter(v => !vistos.has(v.key) && vistos.add(v.key));
    const man = trailerManual(it, ex);
    const trs = man ? [man] : await trailersES(it, vids, ex);
    if(detalleActual !== it) return;
    it._trs = trs;
    ex.trailerKey = trs.length ? trs[0].key : null;
    ex.trailerLabel = trs.length ? trs[0].label : '';
    ex.ytMotivo = ytMotivo;
    pintarModal(it, ex);
  }catch(e){
    if(detalleActual === it) pintarModal(it, {overview:it.overview, genres:[], credits:null, trailerKey:null});
  }
}

/* ========= PANEL: BÚSQUEDA / MI LISTA ========= */
const panel = document.getElementById('panel');
const q = document.getElementById('q');
const results = document.getElementById('results');
const pTitle = document.getElementById('pTitle');
const sTitle = document.getElementById('sTitle');
let panelModo = null, debounce = null, busqId = 0, tendBusq = null;

/* Teclado en pantalla */
const TECLAS = 'abcdefghijklmnopqrstuvwxyzñ0123456789-:.'.split('');
document.getElementById('keys').innerHTML = TECLAS.map(k => `<button type="button" data-k="${k}">${k.toUpperCase()}</button>`).join('');
document.getElementById('skb').addEventListener('click', e => {
  const b = e.target.closest('button'); if(!b) return;
  if(b.dataset.k) q.value += b.dataset.k;
  else if(b.dataset.a === 'space'){ if(q.value && !q.value.endsWith(' ')) q.value += ' '; }
  else if(b.dataset.a === 'del') q.value = q.value.slice(0, -1);
  else if(b.dataset.a === 'clear') q.value = '';
  q.dispatchEvent(new Event('input'));
});

function abrirPanel(modo){
  panelModo = modo;
  document.documentElement.classList.add('lock');
  panel.classList.add('open');
  panel.classList.toggle('search', modo === 'search');
  panel.classList.toggle('list', modo === 'list');
  pTitle.style.display = modo === 'list' ? '' : 'none';
  if(modo === 'search'){
    q.value = ''; pintarSugeridas();
    if(matchMedia('(max-width:760px)').matches || matchMedia('(hover:hover)').matches) setTimeout(() => q.focus(), 50);
  } else pintarLista();
}
function sinRepetidas(arr){
  const ids = new Set(), pos = new Set();
  return arr.filter(it => {
    const k = it.type + it.id;
    if(ids.has(k) || (it.poster && pos.has(it.poster))) return false;
    ids.add(k); if(it.poster) pos.add(it.poster);
    return true;
  });
}
function cerrarPanel(){ bs.modo = null; panel.classList.remove('open'); panelModo = null; document.documentElement.classList.remove('lock'); }
/* La búsqueda ahora tiene scroll: ya no se ocultan portadas; al pintar nuevos resultados se vuelve arriba */
function ajustarResultados(){ results.scrollTop = 0; }
function pintarLista(){
  bs.modo = null;
  pTitle.textContent = 'Mi lista';
  const l = getList();
  results.innerHTML = '';
  if(!l.length){ results.innerHTML = '<div class="msg">Tu lista está vacía. Abre una película y toca <b>+ Mi lista</b>.</div>'; return; }
  l.forEach(it => results.appendChild(crearCard(it)));
}
/* ===== Scroll infinito: al llegar al final de los resultados se cargan más páginas ===== */
let bs = {modo:null, txt:'', page:0, total:1, cargando:false, ids:new Set(), pos:new Set()};
function bsReset(modo, txt){ bs = {modo, txt, page:0, total:1, cargando:false, ids:new Set(), pos:new Set()}; }
function soloNuevos(arr){
  return arr.filter(it => {
    const k = it.type + it.id;
    if(bs.ids.has(k) || (it.poster && bs.pos.has(it.poster))) return false;
    bs.ids.add(k); if(it.poster) bs.pos.add(it.poster);
    return true;
  });
}
async function cargarMas(){
  const mine = bs;
  if(!mine.modo || mine.cargando || mine.page >= mine.total) return;
  mine.cargando = true;
  const pg = mine.page + 1;
  const sent = document.createElement('div');
  sent.className = 'msg mas'; sent.textContent = pg === 1 ? 'Cargando…' : 'Cargando más…';
  results.appendChild(sent);
  try{
    const d = mine.modo === 'search'
      ? await tmdb('/search/multi', {query:mine.txt, include_adult:'false', page:pg})
      : await tmdb('/trending/all/week', {page:pg});
    if(mine !== bs) return;
    mine.page = pg; mine.total = Math.min(d.total_pages || 1, 500);
    sent.remove();
    let items = (d.results || []).filter(x => (x.media_type === 'movie' || x.media_type === 'tv') &&
      (mine.modo === 'search' ? (x.poster_path || x.backdrop_path) : x.poster_path)).map(x => norm(x));
    items = soloNuevos(items);
    if(pg === 1){
      if(mine.modo === 'search'){
        if(!items.length){ sTitle.textContent = 'Sin resultados'; results.innerHTML = `<div class="msg">No encontramos nada para "<b>${esc(mine.txt)}</b>". Prueba con otro título.</div>`; return; }
        sTitle.textContent = `Resultados para “${mine.txt}”`;
      } else sTitle.textContent = 'Más relevantes ahora';
    }
    items.forEach(it => results.appendChild(crearCard(it)));
  }catch(e){
    if(mine === bs){
      sent.remove();
      if(pg === 1) results.innerHTML = '<div class="msg"><b>No se pudo cargar.</b> Revisa tu conexión a internet.</div>';
      else mine.total = mine.page; /* deja de insistir si falla una página posterior */
    }
  }finally{
    mine.cargando = false;
    if(mine === bs) llenarPantalla();
  }
}
/* Si lo cargado aún no llena el área (no hay scroll), se pide la siguiente página */
function llenarPantalla(){
  if(bs.modo && bs.page < bs.total && results.scrollHeight <= results.clientHeight + 40) cargarMas();
}
results.addEventListener('scroll', () => {
  if(bs.modo && results.scrollTop + results.clientHeight >= results.scrollHeight - 400) cargarMas();
}, {passive:true});
function iniciarLista(modo, txt){
  bsReset(modo, txt || '');
  results.innerHTML = ''; results.scrollTop = 0;
  if(modo === 'trend') sTitle.textContent = 'Más relevantes ahora';
  cargarMas();
}
/* Sin texto: lo más relevante de la semana, como en Netflix */
function pintarSugeridas(){ iniciarLista('trend'); }
q.addEventListener('input', () => {
  clearTimeout(debounce);
  const txt = q.value.trim();
  if(!txt){ pintarSugeridas(); return; }
  debounce = setTimeout(() => iniciarLista('search', txt), 300);
});
document.getElementById('pClose').onclick = () => { cerrarPanel(); marcarNav('home'); };

/* ========= NAVEGACIÓN ========= */
function marcarNav(go){ document.querySelectorAll('#nav button').forEach(b => b.classList.toggle('active', b.dataset.go === go)); }
document.getElementById('nav').addEventListener('click', e => {
  const b = e.target.closest('button'); if(!b) return;
  const go = b.dataset.go;
  if(go === 'search' || go === 'list'){ abrirPanel(go); marcarNav(go); return; }
  cerrarPanel(); marcarNav(go);
  if(go === 'home') window.scrollTo({top:0, behavior:'smooth'});
  else { const r = document.getElementById('row-' + go); if(r) r.scrollIntoView({behavior:'smooth', block:'start'}); }
});
document.addEventListener('keydown', e => {
  if(e.key === 'Escape'){ if(modal.classList.contains('open')) cerrarModal(); else if(panelModo){ cerrarPanel(); marcarNav('home'); } }
});

iniciarHero();
</script>
<script>
/* Navegación con mando de TV / teclado: tarjetas y episodios se pueden enfocar y abrir con Enter o Espacio */
(function(){
  var pend = false;
  function marcar(){
    pend = false;
    document.querySelectorAll('.card:not([tabindex]),.ep:not([tabindex])').forEach(function(el){
      el.setAttribute('tabindex','0'); el.setAttribute('role','button');
    });
  }
  function pedir(){ if(!pend){ pend = true; requestAnimationFrame(marcar); } }
  new MutationObserver(pedir).observe(document.body,{childList:true,subtree:true});
  pedir();
  document.addEventListener('keydown', function(e){
    if(e.key !== 'Enter' && e.key !== ' ') return;
    var el = e.target && e.target.closest ? e.target.closest('.card,.ep') : null;
    if(el && el === e.target){ e.preventDefault(); el.click(); }
  });
})();
</script>
<script>
/* iOS/Safari ignora user-scalable=no: se bloquea el pellizco por código */
(function(){
  ['gesturestart','gesturechange','gestureend'].forEach(function(t){
    document.addEventListener(t, function(e){ e.preventDefault(); }, {passive:false});
  });
  document.addEventListener('touchmove', function(e){
    if(e.touches && e.touches.length > 1) e.preventDefault();
  }, {passive:false});
})();
</script>
</body>
